/* Carte template d'une vue custom : le Jinja est evalue par Home Assistant,
 * jamais ici. `render_template` est une SOUSCRIPTION : HA re-evalue et pousse
 * une nouvelle valeur des qu'une entite referencee change — le direct est
 * gratuit, aucun poll. `report_errors` transforme un template invalide en
 * message d'erreur au lieu d'une souscription silencieusement morte. */
function CvTemplateCard({ def, hass }) {
  const [out, setOut] = useState(null);
  const [err, setErr] = useState(null);
  const conn = hass && hass.connection;
  useEffect(() => {
    setOut(null); setErr(null);
    if (!conn || !def.src) return;
    let unsub = null, mort = false;
    conn.subscribeMessage((msg) => {
      if (mort || !msg) return;
      if (msg.error) { setErr(String(msg.error)); return; }
      setErr(null);
      setOut(msg.result != null ? String(msg.result) : '');
    }, { type: 'render_template', template: def.src, report_errors: true })
      .then(u => { if (mort) { try { u(); } catch {} } else unsub = u; })
      .catch(e => { if (!mort) setErr(String((e && e.message) || e)); });
    return () => { mort = true; if (unsub) { try { unsub(); } catch {} } };
  }, [conn, def.src]);
  const attente = out == null && !err;
  return (
    <div className="o-piece" style={{ background: 'linear-gradient(180deg,var(--o-surfA),var(--o-surfB))', border: 'var(--o-bw,1px) solid var(--o-bd2)', borderRadius: 'var(--o-radius,18px)', padding: 16, boxShadow: 'var(--o-shadow,0 10px 26px rgba(0,0,0,.3))' }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12 }}>
        <span style={{ width: 40, height: 40, borderRadius: 14, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--o-s1)', color: 'var(--o-text3)' }}><Fi i="brackets-curly" size={16} /></span>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 12, fontWeight: 700, color: 'var(--o-text3)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{def.name || tr('Carte template') /* le repli de `nomCarte`, dans la langue de l'écran (audit du 03/10) */}</div>
          {err
            ? <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--o-bad)', marginTop: 4, whiteSpace: 'pre-wrap', wordBreak: 'break-word', maxHeight: 96, overflow: 'auto' }}>{err}</div>
            : <div style={{ fontSize: 15, fontWeight: 700, marginTop: 4, whiteSpace: 'pre-wrap', wordBreak: 'break-word', maxHeight: 132, overflowY: 'auto', lineHeight: 1.45, opacity: attente ? .45 : 1 }}>{attente ? '…' : (out === '' ? '—' : out)}</div>}
        </div>
      </div>
    </div>
  );
}

/* « Normal » d'une vitesse a sa clé à sens : la nue est l'état d'un capteur,
 * « Normalnie » (un adverbe) en polonais, entre « Cichy » et « Mocny »
 * (relecture du 03/10). */
const FAN_FR = () => ({ quiet: tr('Silencieux'), normal: trSens('Normal · réglage'), max: 'Max', max_plus: 'Max+', standard: trSens('Normal · réglage'), strong: tr('Fort') });
/* Sélecteur compact façon fiche native : un bouton qui dit la valeur courante,
 * un menu dépoli qui liste les autres. Partagé : vitesse d'aspiration,
 * préréglages de thermostat — partout où des chips feraient brouillon. */
function MenuDeroulant({ icone = null, etiquette, valeur, options, surChoix, rendre = (v) => v }) {
  /* La liste est celle de tous les menus (`ListeChoix`) : même panneau, même
   * taille, même clavier (retour du 18/09). Le bouton reste celui de la
   * fiche — l'étiquette au-dessus de la valeur. */
  return (
    <div role="presentation" style={{ position: 'relative', display: 'flex', flexDirection: 'column', alignItems: 'center' }} onClick={(e) => e.stopPropagation()}>
      <ListeChoix value={valeur} onChange={surChoix} label={etiquette} options={(options || []).map(v => ({ id: v, label: String(rendre(v)) }))}
        style={{ padding: '7px 13px', borderRadius: 14, background: 'var(--o-s1)', border: 'var(--o-bw,1px) solid var(--o-bd2)', color: 'var(--o-text1)' }}>
        {() => (
          <>
            {icone && <Fi i={icone} size={14} color="var(--o-text2)" />}
            <span style={{ display: 'flex', flexDirection: 'column', lineHeight: 1.25 }}>
              <span style={{ fontSize: 10, fontWeight: 700, color: 'var(--o-text3)' }}>{etiquette}</span>
              <span style={{ fontSize: 12, fontWeight: 700, whiteSpace: 'nowrap' }}>{valeur != null ? rendre(valeur) : '—'}</span>
            </span>
          </>
        )}
      </ListeChoix>
    </div>
  );
}
/* `dense` : la COMPACTE — une seule ligne (icône, nom, état) et le contrôle
 * primaire à droite, JAMAIS de rangée de contrôles dessous. La pleine, elle,
 * est la STANDARD : mêmes en-têtes, les contrôles du domaine en dessous. */
/* L'icône suit l'ENTITÉ, pas seulement son domaine : device_class du capteur,
 * type de luminaire, état du moment (porte ouverte/fermée, chauffe en cours).
 * Tous les glyphes sont vérifiés dans uicons-regular-rounded.css. */
function cvIcoEntite(dom, id, st, name) {
  // Ce que l'utilisateur a choisi passe avant tout le reste, et ne change rien
  // d'autre que le glyphe (26/09).
  const mienne = iconeChoisie(id);
  if (mienne) return mienne;
  const a = (st && st.attributes) || {};
  const dc = a.device_class || '';
  const s = st ? st.state : null;
  if (dom === 'light') return LIGHT_TYPE_ICON[lightType({ id, name })] || 'bulb';
  if (dom === 'climate') return a.hvac_action === 'heating' ? 'flame' : a.hvac_action === 'cooling' ? 'snowflake' : 'thermometer-half';
  if (dom === 'sensor') return ({ temperature: 'thermometer-half', humidity: 'humidity', carbon_dioxide: 'smog', pm25: 'smog', pm10: 'smog', aqi: 'smog', power: 'bolt', energy: 'bolt', voltage: 'bolt', current: 'bolt', illuminance: 'brightness', battery: 'battery-half', pressure: 'dashboard', gas: 'flame', moisture: 'raindrops' })[dc] || 'chart-line-up';
  if (dom === 'binary_sensor') return dc === 'door' ? (s === 'on' ? 'door-open' : 'door-closed') : ({ window: 'window-alt', garage_door: 'garage', motion: 'radar', occupancy: 'radar', presence: 'radar', smoke: 'smoke', moisture: 'raindrops', gas: 'flame' })[dc] || 'radar';
  if (dom === 'cover') return (dc === 'garage' || dc === 'gate') ? 'garage' : dc === 'window' ? 'window-alt' : 'blinds';
  if (dom === 'media_player') return dc === 'tv' ? 'screen' : 'tv-music';
  if (dom === 'valve') return 'water';
  /* Serrure : la pastille dit l'ÉTAT, le bouton le GESTE (relecture du lot 16,
   * 05/10). Au téléphone le bouton passe en icône — le cadenas FERMÉ de
   * « verrouiller » — et la pastille, toujours fermée, faisait d'une porte
   * OUVERTE deux cadenas fermés : elle se lisait verrouillée. Seule `locked`
   * garde le cadenas fermé ; tout état de HA où le pêne n'est pas tenu prend le
   * cadenas ouvert : `unlocked`, `unlocking`, `locking` (pas encore fermée),
   * `open`, `opening`, et `jammed` (coincée, rien ne garantit qu'elle tient).
   * Un état inconnu ou absent garde l'icône du domaine : une panne a déjà son
   * liseré (ADR 0048), un cadenas ouvert y affirmerait une porte ouverte. */
  if (dom === 'lock') return ['unlocked', 'unlocking', 'locking', 'open', 'opening', 'jammed'].indexOf(s) >= 0 ? 'unlock' : 'lock';
  return CV_DOM_ICON[dom] || 'bolt';
}
function CvCard({ id, hass, label = null, onOpen = null, dense = false }) {
  const st = hass && hass.states ? hass.states[id] : null;
  const call = (d, s, data) => commanderService(hass, id, d, s, { entity_id: id, ...(data || {}) });
  // Consigne optimiste de la compacte climat (fenêtre fixe 4 s, comme partout).
  const [ovT, setOvT] = useState(null);
  const ovTRef = useRef(0);
  useEffect(() => () => clearTimeout(ovTRef.current), []);
  const poseT = (v) => { setOvT(v); clearTimeout(ovTRef.current); ovTRef.current = setTimeout(() => setOvT(null), 4000); };
  const dom = cvDomain(id);
  const name = label || cvName(st, id);
  const ico = dom === 'switch' ? (iconeChoisie(id) || (cvEstLumiere(id) ? 'bulb' : null)) : cvIcoEntite(dom, id, st, name); // null = prise, SVG maison
  const s = st ? st.state : null;
  const a = (st && st.attributes) || {};
  // Une scène jamais lancée (`unknown`) n'est pas en panne : `enPanne` (05/10).
  const dead = enPanne(id, st);
  // Alarme en cours d'armement : le temps restant, battu à la seconde.
  const cptAlarme = dom === 'alarm_control_panel' ? armCompte(st) : null;
  useSeconde(!!cptAlarme);
  const on = !dead && (dom === 'cover' ? (s === 'open' || s === 'opening') : dom === 'lock' ? s === 'unlocked' : dom === 'media_player' ? s === 'playing' : dom === 'climate' ? s !== 'off' : dom === 'vacuum' ? (s === 'cleaning' || s === 'returning') : dom === 'lawn_mower' ? (s === 'mowing' || s === 'returning') : dom === 'valve' ? s === 'open' : s === 'on');
  // Chaque domaine garde sa teinte des vues intégrées : lumière = sa couleur RGB ou l'or,
  // climat = le rouge de la vue Climatisation — l'accent bleu pour le reste.
  const rgbHex = dom === 'light' && a.rgb_color ? versHex(a.rgb_color) : null;
  // Climat = ROUGE (retour d'essai 31/08) : l'ambre warn2 rendait jaune.
  const teinte = cvEstLumiere(id) ? (rgbHex || 'var(--o-lampe)') : dom === 'climate' ? 'var(--o-bad)' : dom === 'cover' ? 'var(--o-purple)' : null;
  const teinteLu = rgbHex ? lisibleSurLavis(rgbHex, estClair(), .28) : teinte;
  const teinteTxt = rgbHex || (cvEstLumiere(id) ? 'var(--o-warn)' : dom === 'climate' ? 'var(--o-bad)' : dom === 'cover' ? 'var(--o-purple)' : 'var(--o-accent-soft)');
  const togglable = ['light', 'switch', 'input_boolean', 'fan', 'humidifier', 'siren'].indexOf(dom) >= 0;
  // Presque tout s'ouvre : les domaines à fiche dédiée, et tout appareil du
  // registre via la fiche universelle. Seuls les capteurs texte restent muets.
  // Un capteur qui porte une DATE ou une heure n'est pas une mesure :
  // `parseFloat` y lisait l'année (« 2026 ») ou l'heure (« 7 »), et un tap
  // ouvrait une courbe (05/10).
  const dateTxt = dom === 'sensor' ? texteDate(st) : null;
  const ouvrable = !dead && !!onOpen && ((dom === 'sensor' && dateTxt == null && !isNaN(parseFloat(s)))
    || ['light', 'climate', 'cover', 'media_player', 'vacuum', 'lawn_mower', 'fan', 'lock', 'switch', 'humidifier', 'valve', 'water_heater', 'siren', 'binary_sensor', 'input_boolean', 'alarm_control_panel'].indexOf(dom) >= 0);
  const runnable = { scene: ['scene', 'turn_on', tr('Activer')], script: ['script', 'turn_on', tr('Exécuter')], button: ['button', 'press', tr('Appuyer')], input_button: ['input_button', 'press', tr('Appuyer')], automation: ['automation', 'trigger', tr('Exécuter')] }[dom];
  // L'icône du geste, montrée À LA PLACE du mot sur une carte étroite (05/10).
  const icoRun = { button: 'cursor-finger', input_button: 'cursor-finger' }[dom] || 'play';
  let stateTxt;
  if (dead) stateTxt = tr('Indisponible');
  else if (dom === 'light') stateTxt = on ? (tr('Allumé') + (a.brightness ? ' · ' + Math.round(a.brightness / 255 * 100) + '%' : '')) : tr('Éteint');
  else if (togglable) stateTxt = on ? tr('Allumé') : tr('Éteint');
  else if (dom === 'climate') stateTxt = (a.current_temperature != null ? decMax(a.current_temperature, 1) + '°' : '—') + (a.temperature != null ? ' → ' + decMax(a.temperature, 1) + '°' : '') + (s !== 'off' ? '' : ' · ' + tr('Éteint'));
  else if (dom === 'cover') stateTxt = s === 'opening' ? tr('Ouverture…') : s === 'closing' ? tr('Fermeture…') : on ? (tr('Ouvert') + (a.current_position != null && a.current_position < 100 ? ' · ' + a.current_position + '%' : '')) : tr('Fermé');
  // Serrure : les sept états de HA, avec les mots de sa fiche — la pastille
  // ouverte d'une serrure `jammed` s'écrivait « jammed », brut et en anglais
  // dans toutes les langues (contre-relecture du lot 16, 05/10).
  else if (dom === 'lock') stateTxt = ({ locked: tr('Verrouillée'), unlocked: tr('Déverrouillée'), locking: tr('Verrouillage…'), unlocking: tr('Déverrouillage…'), jammed: tr('Bloquée'), open: tr('Ouverte'), opening: tr('Ouverture…') })[s] || String(s);
  else if (dom === 'alarm_control_panel') stateTxt = s === 'disarmed' ? tr('Désarmée') : s === 'triggered' ? tr('ALERTE') : (s === 'arming' || s === 'pending') ? (cptAlarme ? tr('Activation dans {n} s', { n: cptAlarme.reste }) : tr('Activation en cours…')) : s === 'armed_home' ? tr('Maison') : s === 'armed_night' ? tr('Nuit') : tr('Armée');
  else if (dom === 'media_player') stateTxt = s === 'playing' ? (a.media_title || tr('Lecture')) : s === 'paused' ? tr('En pause') : s === 'off' ? tr('Éteint') : tr('Inactif');
  else if (dom === 'binary_sensor') stateTxt = s === 'on' ? tr('Détecté') : tr('RAS');
  else if (dom === 'vacuum' || dom === 'lawn_mower') stateTxt = ({ docked: tr('Sur la base'), cleaning: tr('Nettoyage'), mowing: tr('Tonte'), returning: tr('Retour à la base'), paused: tr('En pause'), idle: tr('Inactif'), error: tr('Erreur') })[s] || String(s);
  else if (dom === 'valve') stateTxt = s === 'open' ? tr('Ouvert') : s === 'closed' ? tr('Fermé') : String(s);
  else if (dom === 'person') stateTxt = s === 'home' ? tr('Présent') : tr('Absent');
  else if (dom === 'sensor' && dateTxt != null) stateTxt = dateTxt;
  else if (dom === 'sensor') stateTxt = (isNaN(parseFloat(s)) ? s : parseFloat(s)) + (a.unit_of_measurement ? ' ' + a.unit_of_measurement : '');
  // scene/script/button : état = date de dernière exécution. Un `event` aussi :
  // jamais tiré (`unknown`, plus en panne), il dit « — », pas « unknown » (05/10).
  else if (runnable || dom === 'event' || /^\d{4}-\d\d-\d\dT/.test(String(s))) stateTxt = relTime(s) || '—';
  else stateTxt = String(s);
  /* Le sous-titre AFFICHÉ, une seule variable pour l'œil et pour le nom de la
   * carte (lot 13 de l'audit du 03/10). Compacte climat : la consigne vit
   * entre les boutons — le sous-titre ne garde que la température relevée. */
  const sousTitre = dense && dom === 'climate' && a.current_temperature != null ? tr('actuel {n}°', { n: decMax(a.current_temperature, 1) }) : stateTxt;
  return (
    /* La carte n'englobe plus ses commandes (lot 13 de l'audit du 03/10, motif
     * de l'ADR 0074). Racine `role="button"`, elle rendait sa descendance
     * présentationnelle : interrupteur, curseur, « Armer », « Verrouiller »,
     * flèches d'un volet disparaissaient d'un lecteur d'écran
     * (`nested-interactive`), et son nom « Ouvrir Volet salon » taisait l'état
     * affiché tout en prenant celui du bouton « Ouvrir » du volet. Le geste
     * « ouvrir la fiche » passe par la `Surface`, premier enfant, nommée de ce
     * que la carte affiche (« Volet salon, Ouvert · 60% »). Chaque commande
     * est positionnée : peinte après la surface, elle reçoit son clic. La
     * rangée, elle, ne l'est plus : un clic sur l'icône, le nom, l'état ou la
     * consigne ouvre la fiche, comme avant. */
    <div className={'o-piece' + (dense ? ' o-cvdense' : '') + (dead ? ' o-panne' : '') + ' o-cvcarte'}
      style={{ position: 'relative', background: on ? `linear-gradient(180deg,${hx(teinte || 'var(--o-accent)', .12)},transparent), linear-gradient(180deg,var(--o-surfA),var(--o-surfB))` : 'linear-gradient(180deg,var(--o-surfA),var(--o-surfB))', border: LISERE, borderRadius: 'var(--o-radius,18px)', padding: dense ? '12px 14px' : 16, boxShadow: 'var(--o-shadow,0 10px 26px rgba(0,0,0,.3))', opacity: dead ? .55 : 1, cursor: ouvrable ? 'pointer' : 'default', transition: 'all .25s', ...(dense ? { height: '100%', boxSizing: 'border-box', display: 'flex', flexDirection: 'column', justifyContent: 'center' } : {}) }}>
      {ouvrable && <Surface onClick={() => onOpen(id)} label={nomCarte(name, sousTitre)} />}
      <div className="o-cvrow" style={{ display: 'flex', alignItems: 'center' }}>
        <span className="o-cvpastille" style={{ background: on ? (teinte ? hx(teinte, .16) : 'rgba(var(--o-accent-rgb),.16)') : 'var(--o-s1)', color: on ? (teinteLu || 'var(--o-accent-soft)') : 'var(--o-text3)' }}>{/* `Ico` et non `Fi` : une icone CHOISIE peut etre un dessin, que `Fi`
                  * aurait cherche dans la police et rendu vide. */}
          {ico ? <Ico name={ico} size={dense ? 15 : 17} /> : <PlugIcon size={dense ? 15 : 17} />}</span>
        <div className="o-cvtxt">
          <div style={{ fontSize: 14, fontWeight: 700, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{name}</div>
          <div style={{ fontSize: 12, fontWeight: 600, color: on ? (teinte ? teinteTxt : 'var(--o-accent-soft)') : 'var(--o-text3)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
            {sousTitre}
          </div>
        </div>
        {togglable && !dead && <span role="switch" aria-checked={on} tabIndex={0} aria-label={on ? tr('Éteindre {nom}', { nom: name }) : tr('Allumer {nom}', { nom: name })} onKeyDown={(e) => { e.stopPropagation(); if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); call('homeassistant', on ? 'turn_off' : 'turn_on'); } }} onClick={(e) => { e.stopPropagation(); call('homeassistant', on ? 'turn_off' : 'turn_on'); }} style={{ width: 44, height: 25, borderRadius: 14, background: on ? 'var(--o-accent-fond)' : 'var(--o-bd1)', position: 'relative', cursor: 'pointer', flexShrink: 0, transition: 'background .25s' }}><span style={{ position: 'absolute', top: 3, left: on ? 22 : 3, width: 19, height: 19, borderRadius: '50%', background: '#fff', transition: 'left .32s cubic-bezier(.34,1.56,.64,1)', boxShadow: '0 2px 5px rgba(0,0,0,.3)' }} /></span>}
        {/* Chaque commande dit son geste PUIS l'appareil (lot 13 de l'audit
          * du 03/10) : hors de la carte-bouton, « Activer » ou « Pause » seuls
          * ne disaient plus de quoi. Positionnée, elle passe sur la surface.
          * Exécuter, la serrure et l'alarme portent leur mot ET leur icône
          * (`o-cvact`) : sur une carte étroite, compacte ou standard, l'icône
          * remplace le mot (index.css) et le nom garde sa place (05/10). */}
        {runnable && !dead && <button className="o-cvact" aria-label={runnable[2] + ' ' + name} title={runnable[2]} onClick={(e) => { e.stopPropagation(); call(runnable[0], runnable[1]); }} style={{ position: 'relative', borderRadius: 10, background: 'rgba(var(--o-accent-rgb),.14)', border: 'none', color: 'var(--o-accent-soft)', fontWeight: 700, fontSize: 12, cursor: 'pointer', flexShrink: 0 }}><span className="o-cvact-ico"><Ico name={icoRun} size={14} /></span><span className="o-cvact-mot">{runnable[2]}</span></button>}
        {dom === 'lock' && !dead && <button className="o-cvact" aria-label={(s === 'locked' ? tr('Déverrouiller') : tr('Verrouiller')) + ' ' + name} title={s === 'locked' ? tr('Déverrouiller') : tr('Verrouiller')} onClick={(e) => { e.stopPropagation(); call('lock', s === 'locked' ? 'unlock' : 'lock'); }} style={{ position: 'relative', borderRadius: 10, background: s === 'locked' ? 'rgba(var(--o-ok-rgb),.14)' : 'rgba(var(--o-warn2-rgb),.16)', border: 'none', color: s === 'locked' ? 'var(--o-ok)' : 'var(--o-warn2)', fontWeight: 700, fontSize: 12, cursor: 'pointer', flexShrink: 0 }}><span className="o-cvact-ico"><Ico name={s === 'locked' ? 'unlock' : 'lock'} size={14} /></span><span className="o-cvact-mot">{s === 'locked' ? tr('Déverrouiller') : tr('Verrouiller')}</span></button>}
        {/* Alarme : le geste attendu, comme la serrure — armer quand elle
          * dort, désarmer sinon. Si le panneau réclame un code, le bouton
          * ouvre la fiche plutôt que d'échouer en silence. */}
        {dom === 'alarm_control_panel' && !dead && (() => {
          const dormante = s === 'disarmed';
          const codeVoulu = dormante ? (!!a.code_format && a.code_arm_required !== false) : !!a.code_format;
          // L'armement du bouton suit le panneau : le premier mode qu'il offre
          // (absent d'abord, le plus courant). Aucun mode déclaré → pas de
          // bouton d'armement, la fiche reste la voie.
          const armements = armChips(a, s).filter(c => c[1] !== 'alarm_disarm');
          const svcArm = (armements.find(c => c[1] === 'alarm_arm_away') || armements[0] || [])[1] || null;
          if (dormante && !svcArm) return null;
          const [bg, col] = dormante ? ['rgba(var(--o-accent-rgb),.14)', 'var(--o-accent-soft)']
            : s === 'triggered' ? ['rgba(var(--o-bad-rgb),.16)', 'var(--o-bad)']
              : ['rgba(var(--o-ok-rgb),.14)', 'var(--o-ok)'];
          return (
            <button className="o-cvact" aria-label={(dormante ? tr('Armer') : tr('Désarmer')) + ' ' + name} title={dormante ? tr('Armer') : tr('Désarmer')} onClick={(e) => {
              e.stopPropagation();
              if (codeVoulu) { if (onOpen) onOpen(id); return; }
              call('alarm_control_panel', dormante ? svcArm : 'alarm_disarm');
            }} style={{ position: 'relative', borderRadius: 10, background: bg, border: 'none', color: col, fontWeight: 700, fontSize: 12, cursor: 'pointer', flexShrink: 0 }}><span className="o-cvact-ico"><Ico name={dormante ? (ICONES_ARMEMENT[svcArm] || ICONES_ARMEMENT.alarm_arm_away) : ICONES_ARMEMENT.alarm_disarm} size={14} /></span><span className="o-cvact-mot">{dormante ? tr('Armer') : tr('Désarmer')}</span></button>
          );
        })()}
        {/* Batterie des machines dans l'en-tête, comme la carte de référence. */}
        {(dom === 'vacuum' || dom === 'lawn_mower') && !dead && a.battery_level != null && (
          <span style={{ fontSize: 12, fontWeight: 800, flexShrink: 0, fontVariantNumeric: 'tabular-nums', color: a.battery_level < 20 ? 'var(--o-bad)' : a.battery_level < 50 ? 'var(--o-warn)' : 'var(--o-text2)' }}>{Math.round(a.battery_level)}%</span>
        )}
        {/* Compacte : le contrôle PRIMAIRE du domaine reste sur la ligne —
          * discret, pour laisser le nom respirer. */}
        {dense && !dead && (() => {
          // Pilules rectangulaires sans filet, le dessin de la maquette —
          // le même pour tous les minis de la compacte.
          const mini = { position: 'relative', width: 38, height: 26, borderRadius: 10, border: 'none', background: 'var(--o-s1)', color: 'var(--o-text1)', cursor: 'pointer', flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 800, fontSize: 13, padding: 0 };
          const miniAccent = { ...mini, background: 'var(--o-accent-fond)', color: '#fff' };
          // Climat : la consigne ENTRE les deux boutons, comme la maquette.
          if (dom === 'climate') {
            const base = ovT != null ? ovT : a.temperature;
            const bouge = (d) => { if (base == null) return; const v = commander(hass, id, 'set_temperature', base + d, 'temperature'); poseT(v != null ? v : base + d); };
            /* Groupe serré, ancré à droite — l'espace libre reste à gauche.
             * PLUS SERRÉ QUE LES AUTRES depuis le gabarit à deux rangées
             * (05/10) : il partage sa ligne avec l'ICÔNE, qui ne s'efface plus.
             * 148 px de contenu au téléphone, moins 26 d'icône et 9 d'écart, il
             * lui reste 113. À 38 px de bouton et 8 d'écart il en demandait 126
             * et le « + » tombait à la ligne, la carte débordant de 26 px sur sa
             * voisine. À 30 et 4 il en prend 102, et 113 avec une consigne à
             * trois chiffres (« 101,5° », en Fahrenheit) : la largeur tient
             * PILE. 32 px la ferait déborder — mesuré. */
            const miniClim = { ...mini, width: 30 };
            return (
              <span style={{ display: 'flex', alignItems: 'center', gap: 4, marginLeft: 'auto', flexShrink: 0 }}>
                <button style={miniClim} aria-label={'− ' + name} onClick={(e) => { e.stopPropagation(); bouge(-0.5); }}>−</button>
                <span style={{ fontSize: 14, fontWeight: 800, fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap', minWidth: 34, textAlign: 'center' }}>{base != null ? decMax(base, 1) + '°' : '—'}</span>
                <button style={miniClim} aria-label={'+ ' + name} onClick={(e) => { e.stopPropagation(); bouge(0.5); }}>+</button>
              </span>
            );
          }
          if (dom === 'cover') return (<>
            <button style={mini} aria-label={tr('Ouvrir') + ' ' + name} onClick={(e) => { e.stopPropagation(); call('cover', 'open_cover'); }}><Fi i="angle-up" size={13} /></button>
            <button style={mini} aria-label={tr('Fermer') + ' ' + name} onClick={(e) => { e.stopPropagation(); call('cover', 'close_cover'); }}><Fi i="angle-down" size={13} /></button>
          </>);
          if (dom === 'vacuum' || dom === 'lawn_mower') {
            const geste = on ? tr('Renvoyer au dock') : (dom === 'vacuum' ? tr('Démarrer le nettoyage') : tr('Lancer la tonte'));
            return (
              <button style={miniAccent} title={geste} aria-label={geste + ' ' + name} onClick={(e) => { e.stopPropagation(); call(dom, on ? (dom === 'vacuum' ? 'return_to_base' : 'dock') : (dom === 'vacuum' ? 'start' : 'start_mowing')); }}><Fi i={on ? 'home' : 'play'} size={12} /></button>
            );
          }
          if (dom === 'media_player' && s !== 'off') return (
            /* « Lire », le geste : « Lecture » est l'ÉTAT écrit sur la carte
             * (« Playing » en anglais) — relecture du lot 13, comme la carte
             * lecteur. Sans texte visible, rien ne change à l'écran ; le bouton
             * standard, lui, garde le mot qu'il affiche. */
            <button style={miniAccent} aria-label={(s === 'playing' ? tr('Pause') : tr('Lire')) + ' ' + name} onClick={(e) => { e.stopPropagation(); commander(hass, id, 'play_pause'); }}><Fi i={s === 'playing' ? 'pause' : 'play'} size={12} /></button>
          );
          return null;
        })()}
      </div>
      {/* Standard lumière : la luminosité en dessous — commit au relâcher. */}
      {!dense && dom === 'light' && !dead && (a.brightness != null || (a.supported_color_modes || []).indexOf('brightness') >= 0) && (
        <div className="o-cvrange" role="presentation" style={{ position: 'relative', marginTop: 14, display: 'flex', alignItems: 'center', gap: 10 }} onClick={(e) => e.stopPropagation()} onPointerDown={(e) => e.stopPropagation()}>
          <Fi i="bulb" size={13} color="var(--o-text3)" />
          {/* Le curseur s'appelait « {n} % de luminosité » avec un `n` VIDE :
            * le nom lu était donc « % de luminosité », et rien ne disait de
            * quelle lampe. Un curseur se nomme par ce qu'il COMMANDE — sa
            * valeur, elle, est déjà dite par le curseur lui-même. Même formule
            * que les jauges des cartes de pièce. */}
          <input type="range" min="1" max="100" key={on ? Math.round((a.brightness || 0) / 255 * 100) : 0}
            defaultValue={on ? Math.round((a.brightness || 0) / 255 * 100) : 0} aria-label={tr('Luminosité') + ' ' + name}
            onPointerUp={(e) => call('light', 'turn_on', { brightness_pct: +e.target.value })}
            onKeyUp={(e) => { if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') call('light', 'turn_on', { brightness_pct: +e.target.value }); }}
            style={{ flex: 1, minWidth: 0 }} />
        </div>
      )}
      {!dense && dom === 'climate' && !dead && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginTop: 12 }}>
          <button aria-label={'− ' + name} onClick={(e) => { e.stopPropagation(); if (a.temperature != null) commander(hass, id, 'set_temperature', a.temperature - .5); }} style={{ position: 'relative', flex: 1, padding: 8, borderRadius: 10, background: 'var(--o-s1)', border: 'var(--o-bw,1px) solid var(--o-bd2)', color: 'var(--o-text)', fontWeight: 800, fontSize: 15, cursor: 'pointer' }}>−</button>
          <span style={{ fontSize: 15, fontWeight: 800, minWidth: 52, textAlign: 'center' }}>{a.temperature != null ? decMax(a.temperature, 1) + '°' : '—'}</span>
          <button aria-label={'+ ' + name} onClick={(e) => { e.stopPropagation(); if (a.temperature != null) commander(hass, id, 'set_temperature', a.temperature + .5); }} style={{ position: 'relative', flex: 1, padding: 8, borderRadius: 10, background: 'var(--o-s1)', border: 'var(--o-bw,1px) solid var(--o-bd2)', color: 'var(--o-text)', fontWeight: 800, fontSize: 15, cursor: 'pointer' }}>+</button>
        </div>
      )}
      {!dense && dom === 'cover' && !dead && (
        <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
          {/* Trois flèches nues : sans nom, un lecteur d'écran n'annonçait que
            * « bouton » trois fois de suite (plan M7). */}
          {[['open_cover', 'angle-up', tr('Ouvrir')], ['stop_cover', 'square', tr('Stop')], ['close_cover', 'angle-down', tr('Fermer')]].map(([svc, gi, nom]) => (
            <button key={svc} aria-label={nom + ' ' + name} title={nom} onClick={(e) => { e.stopPropagation(); call('cover', svc); }} style={{ position: 'relative', flex: 1, padding: 9, borderRadius: 10, background: 'var(--o-s1)', border: 'var(--o-bw,1px) solid var(--o-bd2)', color: 'var(--o-text1)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Fi i={gi} size={14} /></button>
          ))}
        </div>
      )}
      {!dense && dom === 'media_player' && !dead && s !== 'off' && (
        <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
          <button aria-label={(s === 'playing' ? tr('Pause') : tr('Lecture')) + ' ' + name} onClick={(e) => { e.stopPropagation(); commander(hass, id, 'play_pause'); }} style={{ position: 'relative', flex: 1, padding: 9, borderRadius: 10, background: 'var(--o-s1)', border: 'var(--o-bw,1px) solid var(--o-bd2)', color: 'var(--o-text1)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, fontWeight: 700, fontSize: 12 }}><Fi i={s === 'playing' ? 'pause' : 'play'} size={13} />{s === 'playing' ? tr('Pause') : tr('Lecture')}</button>
        </div>
      )}
      {/* Machines : les MÊMES contrôles que la fiche native Home Assistant,
        * dérivés de supported_features — aucun script, aucune configuration. */}
      {!dense && (dom === 'vacuum' || dom === 'lawn_mower') && !dead && (() => {
        const f = a.supported_features || 0;
        const btns = [];
        if (dom === 'vacuum') {
          const enCours = s === 'cleaning';
          if (enCours ? (f & 4) : (f & 8192)) btns.push([enCours ? 'pause' : 'play', enCours ? 'pause' : 'start', enCours ? tr('Pause') : tr('Démarrer le nettoyage')]);
          if ((f & 8) && (s === 'cleaning' || s === 'returning' || s === 'paused')) btns.push(['stop', 'stop', tr('Stop')]);
          if (f & 16) btns.push(['home', 'return_to_base', tr('Renvoyer au dock')]);
          if (f & 512) btns.push(['marker', 'locate', tr('Localiser')]);
        } else {
          const enCours = s === 'mowing';
          if (enCours ? (f & 2) : (f & 1)) btns.push([enCours ? 'pause' : 'play', enCours ? 'pause' : 'start_mowing', enCours ? tr('Pause') : tr('Lancer la tonte')]);
          if (f & 4) btns.push(['home', 'dock', tr('Renvoyer au dock')]);
        }
        // Boutons RONDS alignés à gauche, comme la carte de référence — le
        // premier (l'action principale) porte l'accent ; la vitesse
        // d'aspiration ferme la rangée, discrète, à droite.
        return btns.length > 0 && (
          <div style={{ display: 'flex', gap: 10, marginTop: 12, alignItems: 'center' }}>
            {btns.map(([gi, svc, lbl], bi) => (
              <button key={svc} title={lbl} aria-label={lbl + ' ' + name} onClick={(e) => { e.stopPropagation(); call(dom, svc); }}
                style={{ position: 'relative', width: 40, height: 40, borderRadius: '50%', flexShrink: 0, border: bi === 0 ? 'none' : 'var(--o-bw,1px) solid var(--o-bd2)', background: bi === 0 ? 'var(--o-accent-fond)' : 'var(--o-s1)', color: bi === 0 ? '#fff' : 'var(--o-text1)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 0 }}><Fi i={gi} size={14} /></button>
            ))}
            {dom === 'vacuum' && Array.isArray(a.fan_speed_list) && a.fan_speed_list.length > 1 && (
              <div style={{ marginLeft: 'auto' }}>
                <MenuDeroulant icone="wind" etiquette={tr('Vitesse')} valeur={a.fan_speed} options={a.fan_speed_list}
                  rendre={(v) => FAN_FR()[v] || v} surChoix={(v) => call('vacuum', 'set_fan_speed', { fan_speed: v })} />
              </div>
            )}
          </div>
        );
      })()}
      {!dense && dom === 'valve' && !dead && (
        <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
          <button aria-label={(on ? tr('Fermer') : tr('Ouvrir')) + ' ' + name} onClick={(e) => { e.stopPropagation(); call('valve', on ? 'close_valve' : 'open_valve'); }} style={{ position: 'relative', flex: 1, padding: 9, borderRadius: 10, background: 'var(--o-s1)', border: 'var(--o-bw,1px) solid var(--o-bd2)', color: 'var(--o-text1)', cursor: 'pointer', fontWeight: 700, fontSize: 12 }}>{on ? tr('Fermer') : tr('Ouvrir')}</button>
        </div>
      )}
      {/* Les épingles sont des lignes à commandes : positionnées, elles passent
        * sur la surface (lot 13 de l'audit du 03/10). Vide, l'enveloppe ne
        * mesure rien. */}
      {!dense && <div style={{ position: 'relative' }}><Epingles pourId={id} hass={hass} /></div>}
    </div>
  );
}

/* ════════════ CATALOGUE DE CARTES des vues custom ════════════
 * Le TYPE se choisit à l'ajout — jamais par un geste implicite : quand une
 * entité admet plusieurs cartes, le sheet d'ajout les propose. Chaque entrée
 * typée de `cv.ents` s'écrit { t, id } ; la chaîne nue reste la compacte. */

// Le liseré du réglage (04/10) : le cadre de toutes les cartes de vue perso.
const CV_CADRE = { background: 'linear-gradient(180deg,var(--o-surfA),var(--o-surfB))', border: LISERE, borderRadius: 'var(--o-radius,18px)', padding: 16, boxShadow: 'var(--o-shadow,0 10px 26px rgba(0,0,0,.3))', boxSizing: 'border-box', display: 'flex', flexDirection: 'column' };

/* Un switch n'est une lumière que s'il est déclaré interrupteur-lumière ;
 * sinon c'est une prise ou un appareil : icône prise, teinte accent — pas l'or. */
const cvEstLumiere = (id) => String(id).indexOf('light.') === 0 || (String(id).indexOf('switch.') === 0 && switchLights().indexOf(id) >= 0);
// La fonte UICons n'a pas de prise : SVG maison, comme BulbIcon.
const PlugIcon = ({ size = 19 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M9 2v6M15 2v6" />
    <path d="M6 8h12v3a6 6 0 0 1-6 6 6 6 0 0 1-6-6V8z" />
    <path d="M12 17v5" />
  </svg>
);

/** Les cartes qui vont à une entité, la première étant proposée en premier.
 * Partout : COMPACTE (une ligne, contrôle primaire, rien dessous) et STANDARD
 * (les contrôles du domaine en dessous) — puis les spécialisées du domaine. */
function cvTypesPour(id) {
  const d = String(id).split('.')[0];
  // La CHIP ferme chaque liste : c'est la plus petite carte du catalogue, une
  // pastille pour une entité (retour 01/09).
  // Le « gros interrupteur » a quitté le catalogue le 31/08/2026 (retour
  // d'essai) — les cartes déjà posées continuent de se rendre (CvTyped).
  if (d === 'light' || d === 'switch' || d === 'fan') return ['compacte', 'riche', 'journal', 'chip'];
  if (d === 'cover' || d === 'climate' || d === 'media_player' || d === 'vacuum' || d === 'lawn_mower' || d === 'valve' || d === 'humidifier' || d === 'lock' || d === 'siren' || d === 'water_heater') return ['compacte', 'riche', 'journal', 'chip'];
  if (d === 'scene' || d === 'script' || d === 'button' || d === 'input_button' || d === 'automation') return ['compacte', 'riche', 'chip'];
  // La jauge a quitté le catalogue le 31/08/2026 (« il est moche ») — les
  // cartes déjà posées continuent de se rendre (CvTyped).
  if (d === 'sensor') return ['compacte', 'chiffre', 'graph', 'journal', 'chip'];
  if (d === 'binary_sensor') return ['compacte', 'chiffre', 'journal', 'chip'];
  if (d === 'person') return ['compacte', 'personne', 'journal', 'chip'];
  if (d === 'weather') return ['compacte', 'meteo', 'chip'];
  if (d === 'calendar') return ['agenda', 'calendrier', 'compacte', 'chip'];
  if (d === 'alarm_control_panel') return ['compacte', 'alarme', 'alarmeseule', 'riche', 'chip'];
  if (d === 'camera') return ['camera', 'compacte'];
  return ['compacte', 'riche', 'chip'];
}
const CV_TYPE_NOMS = () => ({ compacte: tr('Compacte'), riche: tr('Standard'), gros: tr('Gros interrupteur'), chiffre: tr('Grand chiffre'), jauge: tr('Jauge'), graph: tr('Graphique 24 h'), journal: tr('Journal'), personne: tr('Présence'), meteo: tr('Météo'), agenda: tr('Agenda'), alarme: tr('Alarme'), horloge: tr('Horloge'), presence: tr('Présence maison'), ouvrants: tr('Ouvrants'), energiemaison: tr('Énergie maison'), air: tr('Qualité air'), alarmeseule: tr('Alarme (seule)'), activite: tr('Activité récente'), camera: tr('Caméra'), calendrier: tr('Calendrier'), localisation: tr('Localisation'), chips: tr('Chips (groupe)'), chip: tr('Chip') });

/* Horloge : l'heure de la maison, sans entité — la carte se suffit. */
function CvClock() {
  const [, tic] = useState(0);
  useEffect(() => { const iv = setInterval(() => tic(n => n + 1), 15000); return () => clearInterval(iv); }, []);
  const d = new Date();
  const h = d.toLocaleTimeString(locale(), { hour: '2-digit', minute: '2-digit' });
  const jour = d.toLocaleDateString(locale(), { weekday: 'long', day: 'numeric', month: 'long' });
  return (
    <div style={{ ...CV_CADRE, alignItems: 'center', justifyContent: 'center', height: '100%' }}>
      <div style={{ fontSize: 34, fontWeight: 800, letterSpacing: '-.02em', fontVariantNumeric: 'tabular-nums', lineHeight: 1 }}>{h}</div>
      <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--o-text2)', marginTop: 6, textTransform: 'capitalize' }}>{jour}</div>
    </div>
  );
}

/* Grand chiffre : la valeur en très grand, l'unité, le nom. Un binaire dit son
 * état en toutes lettres ; la richesse d'un capteur, c'est sa lisibilité. */
/* `onOpen` (lot 13 de l'audit du 03/10) : la carte EST alors le bouton qui
 * ouvre la fiche — elle ne porte aucune commande à protéger —, nommée de ce
 * qu'elle affiche, le nom puis la valeur. Une enveloppe de `CvTyped` la
 * nommait « Ouvrir sensor.co2_sejour » : l'identifiant, épelé. Sans `onOpen`
 * (bibliothèque), elle n'est rien de tout cela. Même chose pour la jauge et
 * le graphique. En panne, le nom dit « Indisponible », comme `CvCard` — pas
 * le tiret de l'écran, ni « — ppm » : l'unité ne suit qu'une vraie valeur
 * (relecture du lot 13). */
function CvBigSensor({ id, hass, onOpen = null }) {
  const st = hass && hass.states ? hass.states[id] : null;
  const a = (st && st.attributes) || {};
  const dom = String(id).split('.')[0];
  const brut = st ? st.state : null;
  const mort = !st || brut === 'unavailable' || brut === 'unknown';
  // Une date, une heure (05/10, suite « dates partout ») : `texteDate`, pas
  // l'année de `parseFloat` en 54 px — et un corps qui la laisse tenir.
  const date = mort ? null : texteDate(st);
  let valeur, unite = '';
  if (mort) valeur = '—';
  else if (dom === 'binary_sensor') {
    const porte = ['door', 'window', 'garage_door', 'opening'].indexOf(a.device_class) >= 0;
    valeur = brut === 'on' ? (porte ? tr('Ouvert') : tr('Détecté')) : (porte ? tr('Fermé') : tr('RAS'));
  } else {
    const n = parseFloat(brut);
    valeur = date != null ? date : isNaN(n) ? brut : decMax(n, 1);
    unite = date != null ? '' : a.unit_of_measurement || '';
  }
  const nom = cvName(st, id);
  return (
    /* eslint-disable-next-line jsx-a11y/no-static-element-interactions, jsx-a11y/no-noninteractive-tabindex */
    <div className={'o-piece' + (mort ? ' o-panne' : '')} role={onOpen ? 'button' : undefined} tabIndex={onOpen ? 0 : undefined}
      aria-label={onOpen ? nomCarte(nom, mort ? tr('Indisponible') : (unite ? valeur + ' ' + unite : valeur)) : undefined} aria-haspopup={onOpen ? 'dialog' : undefined}
      onClick={onOpen ? () => onOpen(id) : undefined}
      onKeyDown={onOpen ? (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onOpen(id); } } : undefined}
      style={{ ...CV_CADRE, height: '100%', minHeight: 150, opacity: mort ? .55 : 1, cursor: onOpen ? 'pointer' : undefined }}>
      <span style={{ width: 40, height: 40, borderRadius: 14, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--o-s1)', color: 'var(--o-text3)' }}><Fi i={CV_DOM_ICON[cvDomain(id)] || 'bolt'} size={17} /></span>
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: 0 }}>
        <div style={{ fontSize: date != null ? 'clamp(20px, 1vw + 14px, 28px)' : 'clamp(32px, 3vw + 12px, 54px)', fontWeight: 800, letterSpacing: '-.02em', lineHeight: 1, fontVariantNumeric: 'tabular-nums', textAlign: 'center' }}>
          {valeur}{unite && <span style={{ fontSize: '.42em', fontWeight: 700, color: 'var(--o-text2)', marginLeft: 6 }}>{unite}</span>}
        </div>
      </div>
      <div style={{ fontSize: 13, fontWeight: 700, color: 'var(--o-text2)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{nom}</div>
    </div>
  );
}

/* Jauge : un arc de cercle. Le pourcentage vient de l'unité « % », sinon des
 * bornes min/max de l'entité — des °C entre min_temp et max_temp se jaugent
 * aussi bien qu'une batterie. */
function CvGauge({ id, hass, onOpen = null }) {
  const st = hass && hass.states ? hass.states[id] : null;
  const a = (st && st.attributes) || {};
  const n = st ? parseFloat(st.state) : NaN;
  const mort = !st || isNaN(n);
  const min = a.min != null ? +a.min : (a.min_temp != null ? +a.min_temp : 0);
  const max = a.max != null ? +a.max : (a.max_temp != null ? +a.max_temp : (a.unit_of_measurement === '%' ? 100 : 100));
  const pct = mort ? 0 : Math.max(0, Math.min(1, (n - min) / (max - min || 1)));
  const basse = a.device_class === 'battery' && n < 20;
  const col = basse ? 'var(--o-bad)' : 'var(--o-accent)';
  // Arc de 240° : de 150° à 390°, rayon 44, épaisseur 9.
  const arc = (p) => {
    const a0 = (150 * Math.PI) / 180, a1 = ((150 + 240 * p) * Math.PI) / 180;
    const x0 = 60 + 44 * Math.cos(a0), y0 = 60 + 44 * Math.sin(a0);
    const x1 = 60 + 44 * Math.cos(a1), y1 = 60 + 44 * Math.sin(a1);
    return `M ${x0} ${y0} A 44 44 0 ${240 * p > 180 ? 1 : 0} 1 ${x1} ${y1}`;
  };
  const valeur = mort ? '—' : decMax(n, 1);
  const unite = a.unit_of_measurement || '';
  const nom = cvName(st, id);
  return (
    /* eslint-disable-next-line jsx-a11y/no-static-element-interactions, jsx-a11y/no-noninteractive-tabindex */
    <div className={'o-piece' + (mort ? ' o-panne' : '')} role={onOpen ? 'button' : undefined} tabIndex={onOpen ? 0 : undefined}
      aria-label={onOpen ? nomCarte(nom, mort ? tr('Indisponible') : (unite ? valeur + ' ' + unite : valeur)) : undefined} aria-haspopup={onOpen ? 'dialog' : undefined}
      onClick={onOpen ? () => onOpen(id) : undefined}
      onKeyDown={onOpen ? (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onOpen(id); } } : undefined}
      style={{ ...CV_CADRE, height: '100%', minHeight: 150, alignItems: 'center', opacity: mort ? .55 : 1, cursor: onOpen ? 'pointer' : undefined }}>
      <div style={{ position: 'relative', width: 120, height: 104, flexShrink: 0 }}>
        <svg width="120" height="120" viewBox="0 0 120 120" style={{ position: 'absolute', top: -4 }}>
          <path d={arc(1)} fill="none" stroke="var(--o-s1)" strokeWidth="9" strokeLinecap="round" />
          {!mort && pct > 0.005 && <path d={arc(pct)} fill="none" stroke={col} strokeWidth="9" strokeLinecap="round" style={{ transition: 'stroke .3s' }} />}
        </svg>
        <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', paddingTop: 6 }}>
          <span style={{ fontSize: 25, fontWeight: 800, fontVariantNumeric: 'tabular-nums' }}>{valeur}</span>
          <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--o-text2)' }}>{unite}</span>
        </div>
      </div>
      <div style={{ marginTop: 'auto', width: '100%', textAlign: 'center', fontSize: 13, fontWeight: 700, color: 'var(--o-text2)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{nom}</div>
    </div>
  );
}

/* Gros interrupteur : toute la carte est le bouton — pensée pour la tablette
 * murale, où viser un petit toggle est une corvée. */
function CvBigToggle({ id, hass }) {
  const st = hass && hass.states ? hass.states[id] : null;
  const on = !!st && st.state === 'on';
  const mort = !st || st.state === 'unavailable';
  // L'or est réservé aux lumières ; une prise ou un appareil s'allume à l'accent, icône prise.
  const lum = cvEstLumiere(id);
  const rgbTok = lum ? 'var(--o-gold-rgb)' : 'var(--o-accent-rgb)';
  const txtCol = lum ? 'var(--o-warn)' : 'var(--o-accent-soft)';
  const toggle = () => commander(hass, id, 'toggle');
  return (
    <button className={'o-piece' + (mort ? ' o-panne' : '')} onClick={toggle} disabled={mort}
      style={{ ...CV_CADRE, height: '100%', minHeight: 150, width: '100%', alignItems: 'center', justifyContent: 'center', gap: 8, cursor: mort ? 'default' : 'pointer', opacity: mort ? .55 : 1, transition: 'all .25s',
        ...(on ? { background: `linear-gradient(160deg,rgba(${rgbTok},${lav(.22)}),transparent 62%), linear-gradient(180deg,var(--o-surfA),var(--o-surfB))` } : {}) }}>
      <span style={{ width: 52, height: 52, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: on ? `rgba(${rgbTok},.2)` : 'var(--o-s1)', color: on ? txtCol : 'var(--o-text3)', boxShadow: on ? `0 0 22px rgba(${rgbTok},.4)` : 'none', transition: 'all .25s', flexShrink: 0 }}>
        {String(id).indexOf('switch.') === 0 && !lum ? <PlugIcon size={23} /> : <Fi i="power" size={23} />}
      </span>
      <span style={{ fontSize: 14, fontWeight: 800, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: '100%' }}>{cvName(st, id)}</span>
      <span style={{ fontSize: 12, fontWeight: 700, color: on ? txtCol : 'var(--o-text3)' }}>{mort ? tr('Indisponible') : on ? tr('Allumé') : tr('Éteint')}</span>
    </button>
  );
}

/* Présence : la personne, son état, depuis quand. */
function CvPerson({ id, hass }) {
  const st = hass && hass.states ? hass.states[id] : null;
  const a = (st && st.attributes) || {};
  const nom = cvName(st, id);
  const home = !!st && st.state === 'home';
  const img = a.entity_picture || null;
  return (
    <div className="o-piece" style={{ ...CV_CADRE, height: '100%', minHeight: 150, alignItems: 'center', justifyContent: 'center', gap: 10 }}>
      <span style={{ position: 'relative', width: 58, height: 58, flexShrink: 0 }}>
        <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', width: '100%', height: '100%', borderRadius: '50%', background: img ? `url("${img}") center/cover` : 'var(--o-s1)', color: home ? 'var(--o-text2)' : 'var(--o-text3)', fontSize: 19, fontWeight: 800, boxShadow: home ? '0 0 0 2.5px var(--o-ok), 0 0 12px rgba(var(--o-ok-rgb),.5)' : '0 0 0 2px var(--o-bd1)', opacity: home || !img ? 1 : .55 }}>{!img && nom.charAt(0).toUpperCase()}</span>
        <span style={{ position: 'absolute', right: -1, bottom: -1, width: 14, height: 14, borderRadius: '50%', background: home ? 'var(--o-ok)' : 'var(--o-text3)', border: '2.5px solid var(--o-surfA)' }} />
      </span>
      <span style={{ fontSize: 14, fontWeight: 800 }}>{nom}</span>
      <span style={{ fontSize: 12, fontWeight: 700, color: home ? 'var(--o-ok)' : 'var(--o-text3)' }}>{home ? tr('Présent') : tr('Absent')}{st && st.last_changed ? ' · ' + relTime(st.last_changed).toLowerCase() : ''}</span>
    </div>
  );
}

/* Météo : la vignette animée de l'accueil, en carte. */
function CvWeather({ id, hass }) {
  const st = hass && hass.states ? hass.states[id] : null;
  const a = (st && st.attributes) || {};
  const S = (hass && hass.states) || {};
  const nuit = S['sun.sun'] ? S['sun.sun'].state === 'below_horizon' : false;
  const wx = st ? haWeatherMode(st.state, nuit) : 'clouds';
  return (
    <div className="o-piece" style={{ ...CV_CADRE, height: '100%', minHeight: 150, position: 'relative', overflow: 'hidden', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
      <WxMini wx={wx} on={true} />
      <WeatherIco wx={wx} size={52} />
      <div style={{ position: 'relative', textAlign: 'center' }}>
        <div style={{ fontSize: 28, fontWeight: 800 }}>{a.temperature != null ? Math.round(a.temperature) : '—'}°</div>
        <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--o-text2)' }}>{st ? haWeatherLabel(st.state) : ''}</div>
      </div>
    </div>
  );
}

/* Agenda : les prochains événements d'UN calendrier — rangées à fond, la
 * prochaine échéance mise en avant (maquette Claude Design 31/08). */
/* CHIPS : l'état de la maison en pastilles, sur une seule rangée.
 *
 * La carte la plus dense du catalogue — ce que les autres disent en 184 px,
 * elle le résume en 88. Chaque pastille naît de ce qui EXISTE : pas de
 * lumière découverte, pas de pastille lumières. Elles ne pilotent rien : une
 * rangée aussi serrée invite au faux geste, la fiche est à un tap ailleurs. */
/* Valeur COURTE d'une entité pour une pastille : ce qui tient à côté de son
 * icône. Une porte n'a pas besoin de mot — son icône et sa couleur le disent
 * déjà ; un capteur, si. */
function chipTexte(id, st) {
  if (!st) return '—';
  const d = String(id).split('.')[0];
  // Sans valeur, rien à dire — comme une entité absente (05/10). La pastille
  // écrivait l'état BRUT, « unknown », « unavailable » en anglais ; pire, une
  // alarme injoignable s'y disait « Armée », une serrure « Déverrouillée ».
  if (st.state === 'unknown' || st.state === 'unavailable') return '—';
  // Scène, bouton, événement : leur état est la date du dernier déclenchement,
  // script et automatisation un on/off — elle dit ce que dit la tuile
  // (`CvCard`) : « — » jamais déclenché, `relTime` sinon, pas l'ISO en clair.
  if (['scene', 'script', 'button', 'input_button', 'automation', 'event'].indexOf(d) >= 0) return relTime(st.state) || '—';
  // Une date, une heure (capteur horodaté, entité `datetime`) : `texteDate`.
  const date = texteDate(st);
  if (date != null) return date;
  const a = st.attributes || {};
  const s = st.state;
  if (d === 'light' || d === 'switch' || d === 'input_boolean' || d === 'fan') return a.brightness != null && s === 'on' ? Math.round(a.brightness / 255 * 100) + ' %' : '';
  if (d === 'climate') return a.current_temperature != null ? decMax(a.current_temperature, 1) + '°' : (a.temperature != null ? decMax(a.temperature, 1) + '°' : '');
  if (d === 'cover') return a.current_position != null ? a.current_position + ' %' : (s === 'open' ? tr('Ouvert') : tr('Fermé'));
  if (d === 'media_player') return s === 'playing' ? (a.media_title || tr('Lecture')) : '';
  if (d === 'alarm_control_panel') return s === 'disarmed' ? tr('Désarmée') : s === 'triggered' ? tr('ALERTE') : tr('Armée');
  if (d === 'person' || d === 'device_tracker') return s === 'home' ? tr('Présent') : tr('Absent');
  if (d === 'binary_sensor') return '';
  if (d === 'sensor') { const n = parseFloat(s); return (isNaN(n) ? String(s) : decMax(n, 1)) + (a.unit_of_measurement ? ' ' + a.unit_of_measurement : ''); }
  if (d === 'lock') return s === 'locked' ? tr('Verrouillée') : tr('Déverrouillée');
  return String(s);
}
/* Un état qui est une DATE ou une HEURE, dit pour l'œil (05/10). `parseFloat`
 * y lisait l'année ou l'heure : la tuile (`CvCard`) d'un capteur horodaté
 * — prochaine alarme du téléphone, dernier passage du facteur — affichait
 * « 2026 », la pastille « 2 026 », un capteur « 07:30 » disait « 7 ».
 * Un horodatage (`device_class: timestamp`, ou un état ISO avec son heure)
 * passe par `relTime` comme dans la fiche (`LigneEntite`) : passé relatif,
 * futur en heure absolue. Une date seule (`device_class: date`) s'écrit par
 * Intl dans la langue de l'écran, l'année si ce n'est pas celle-ci —
 * `relTime` la lirait minuit UTC, « lun. 02:00 ». Une heure seule reste
 * telle quelle. `null` : ni date ni heure, la valeur se lit comme avant. */
function texteDate(st) {
  if (!st) return null;
  const s = String(st.state);
  // L'espace vaut le T (05/10, suite « dates partout ») : un `input_datetime`,
  // un capteur gabarit écrivent « 2026-10-05 07:30:00 », que la fiche lisait
  // « 2 026 ». Remis en T avant `new Date` : sans fuseau, l'heure est LOCALE,
  // et la forme à espace n'est pas garantie par la norme.
  const iso = /^\d{4}-\d\d-\d\d[T ]\d/.test(s);
  if ((st.attributes || {}).device_class === 'timestamp' || iso) return relTime(iso ? s.replace(' ', 'T') : s) || '—';
  const j = /^(\d{4})-(\d\d)-(\d\d)$/.exec(s);
  if (j) {
    // Minuit LOCAL (`new Date(a, m, j)`), pas UTC : à l'ouest de Greenwich,
    // `new Date('2026-10-12')` tombe la veille.
    const q = new Date(+j[1], j[2] - 1, +j[3]);
    return q.toLocaleDateString(locale(), { day: 'numeric', month: 'short', ...(q.getFullYear() !== new Date(Date.now()).getFullYear() ? { year: 'numeric' } : {}) });
  }
  return /^\d\d?:\d\d(:\d\d)?$/.test(s) ? s : null;
}
/* Une pastille est-elle « vive » ? Le même vocabulaire que les cartes : ce qui
 * est allumé, ouvert, en marche ou détecté attire l'œil. */
function chipVif(id, st) {
  if (!st) return false;
  const d = String(id).split('.')[0];
  const s = st.state;
  if (d === 'cover' || d === 'valve') return s === 'open' || s === 'opening';
  if (d === 'climate') return s !== 'off';
  if (d === 'media_player') return s === 'playing';
  if (d === 'lock') return s === 'unlocked';
  if (d === 'alarm_control_panel') return s !== 'disarmed';
  if (d === 'person' || d === 'device_tracker') return s === 'home';
  if (d === 'sensor') return false;
  return s === 'on';
}
/* UNE CHIP, une entité, une carte — la plus petite du catalogue.
 *
 * Elle ne remplit pas sa case : une pastille de 48 px flotte au milieu de la
 * rangée, comme les chips de Home Assistant posées seules. On en pose autant
 * qu'on veut, côte à côte ; c'est le format demandé le 01/09 : « une vraie
 * chip par entité et non rassemblé dans une carte ». */
function CvChip({ id, hass, dc = null }) {
  const S = (hass && hass.states) || {};
  const st = S[id];
  const d = String(id).split('.')[0];
  const vif = chipVif(id, st);
  const col = d === 'cover' ? 'var(--o-purple)' : d === 'climate' ? 'var(--o-bad)'
    : (d === 'light' || d === 'switch') ? 'var(--o-warn)'
      : d === 'alarm_control_panel' ? (st && st.state === 'triggered' ? 'var(--o-bad)' : st && st.state === 'disarmed' ? 'var(--o-ok)' : 'var(--o-warn2)')
        : 'var(--o-accent-soft)';
  const val = chipTexte(id, st);
  const nom = cvName(st, id);
  return (
    <div style={{ height: '100%', display: 'flex', alignItems: 'center' }}>
      {/* Son nom est déjà ce qu'elle affiche, le nom puis la valeur : il vient
        * de son texte. Elle dit seulement ouvrir une fiche (lot 13 de l'audit
        * du 03/10). */}
      {/* Le liseré des autres cartes (relecture du 04/10) : `border: 'none'`
        * en faisait la seule famille sans trait, et sous Atrium, dont le filet
        * `calc(1px - --o-bw)` s'efface dès que Liserés est actif, la seule
        * sans AUCUN contour. Le trait se prend dans les 48 px (border-box). */}
      <button onClick={(e) => { e.stopPropagation(); if (dc && dc.ouvrir) dc.ouvrir(id); }} title={nom}
        aria-haspopup={dc && dc.ouvrir ? 'dialog' : undefined}
        style={{ display: 'flex', alignItems: 'center', gap: 8, width: '100%', minWidth: 0, height: 48, padding: '0 14px', borderRadius: 14, border: LISERE, cursor: 'pointer',
          background: vif ? hx(col, .16) : 'linear-gradient(180deg,var(--o-surfA),var(--o-surfB))',
          color: vif ? col : 'var(--o-text2)', boxShadow: 'var(--o-shadow,0 8px 20px rgba(0,0,0,.26))' }}>
        <Fi i={cvIcoEntite(d, id, st, nom) || 'bolt'} size={15} color={vif ? col : 'var(--o-text3)'} />
        <span style={{ flex: 1, minWidth: 0, textAlign: 'left', fontSize: 12, fontWeight: 700, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', color: 'var(--o-text1)' }}>{nom}</span>
        {val ? <span style={{ fontSize: 12, fontWeight: 800, flexShrink: 0 }}>{val}</span> : null}
      </button>
    </div>
  );
}

function CvChips({ x = null, hass, dc = null, demo = null }) {
  const S = (hass && hass.states) || {};
  /* Une carte chips, c'est SES entités : celles qu'on lui a choisies, chacune
   * cliquable. Le résumé automatique de la maison a été retiré (retour
   * 01/09) — il donnait des pastilles muettes que personne n'avait demandées. */
  const ids = (x && Array.isArray(x.ids)) ? x.ids.filter(i => S[i]) : [];
  const idsSig = ids.join('|');
  const chips = useMemo(() => {
    if (demo) return demo;
    return ids.map(id => {
      const st = S[id];
      const vif = chipVif(id, st);
      const d = String(id).split('.')[0];
      const col = d === 'cover' ? 'var(--o-purple)' : d === 'climate' ? 'var(--o-bad)'
        : (d === 'light' || d === 'switch') ? 'var(--o-warn)'
          : d === 'alarm_control_panel' ? (st.state === 'triggered' ? 'var(--o-bad)' : st.state === 'disarmed' ? 'var(--o-ok)' : 'var(--o-warn2)')
            : 'var(--o-accent-soft)';
      return { id, ic: cvIcoEntite(d, id, st, cvName(st, id)) || 'bolt', txt: chipTexte(id, st), col, vif };
    });
  }, [hass, demo, idsSig]);
  const ouvrir = (c) => { if (c.id && dc && dc.ouvrir) dc.ouvrir(c.id); };
  return (
    /* `justifyContent: center` sur le CADRE, pas sur la rangée : CV_CADRE
     * empile en COLONNE, la rangée était donc collée en haut (retour 01/09).
     * C'est l'axe principal de la colonne qui centre verticalement. */
    <div className="o-piece" style={{ ...CV_CADRE, height: '100%', justifyContent: 'center', overflow: 'hidden' }}>
      {/* Elles défilent plutôt que de rétrécir : une pastille illisible ne dit
        * rien, et la rangée doit tenir sur 88 px quelle que soit la largeur. */}
      <div className="o-chipsrow" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, overflowX: 'auto', scrollbarWidth: 'none', width: '100%' }}>
        {chips.length === 0 && <span style={{ fontSize: 12, fontWeight: 600, color: 'var(--o-text3)' }}>{tr('Aucune pastille — le crayon en ajoute.')}</span>}
        {chips.map((c, i) => {
          const st = { display: 'inline-flex', alignItems: 'center', gap: 6, flexShrink: 0, padding: '7px 11px', borderRadius: 10, whiteSpace: 'nowrap', fontSize: 12, fontWeight: 800, border: 'none', background: c.vif ? hx(c.col, .14) : 'var(--o-s1)', color: c.vif ? c.col : 'var(--o-text2)' };
          const dedans = <>{<Fi i={c.ic} size={12} color={c.vif ? c.col : 'var(--o-text3)'} />}{c.txt}</>;
          // Chaque pastille ouvre la fiche de son entité — la vitrine de la
          // bibliothèque est le seul cas sans fiche à ouvrir. Son nom dit
          // l'entité PUIS la valeur affichée (lot 13 de l'audit du 03/10) :
          // « 65 % » seul ne disait pas de quoi.
          return c.id
            ? <button key={c.id} onClick={(e) => { e.stopPropagation(); ouvrir(c); }} title={cvName(S[c.id], c.id)} aria-label={nomCarte(cvName(S[c.id], c.id), c.txt)} aria-haspopup={dc && dc.ouvrir ? 'dialog' : undefined} style={{ ...st, cursor: 'pointer' }}>{dedans}</button>
            : <span key={i} style={st}>{dedans}</span>;
        })}
      </div>
    </div>
  );
}

function CvAgenda({ id, hass }) {
  const events = useAgenda(hass, useMemo(() => [id], [id]));
  const st = hass && hass.states ? hass.states[id] : null;
  return (
    <div className="o-piece" style={{ ...CV_CADRE, height: '100%', overflow: 'hidden' }}>
      {/* Relecture du 04/10 : à 184 px (rangées de 8), le titre sur deux lignes
        * poussait le 3e événement hors du cadre (1366 px, tablette, téléphone).
        * Une ligne, tronquée — et `flexShrink: 0`, sans quoi `overflow: hidden`
        * ramène sa hauteur minimale à 0 et la colonne qui déborde l'écrase. */}
      <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 8, flexShrink: 0, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{cvName(st, id)} · {tr('7 prochains jours')}</div>
      {events.length === 0 && <div style={{ fontSize: 12, color: 'var(--o-text3)', fontWeight: 600, padding: '10px 0' }}>{tr('Rien de prévu')}</div>}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
        {events.slice(0, 3).map((e, i) => {
          const { jour, heure } = jourAgenda(e);
          return (
            /* Pastille à 4 px de haut et de bas (relecture du 04/10) : à 6, la
             * 3e descendait à 187 px, coupée par le bord d'une carte de 184. */
            <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '4px 10px', borderRadius: 10, background: i === 0 ? 'rgba(var(--o-accent-rgb),.1)' : 'var(--o-s1)' }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 12, fontWeight: 700, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{e.summary}</div>
                <div style={{ fontSize: 11, fontWeight: 600, color: 'var(--o-text2)' }}>{jour}</div>
              </div>
              <span style={{ fontSize: 12, fontWeight: 800, flexShrink: 0, color: i === 0 ? 'var(--o-accent-soft)' : 'var(--o-text2)' }}>{heure || tr('Tâche')}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}
/* Activité récente : le journal de la MAISON — ouvrants, machines, volets,
 * serrures, alarme, capteurs muets — en pastilles colorées par domaine. */
function CvActivite({ hass, demoEvents = null }) {
  const S = (hass && hass.states) || {};
  const ids = useMemo(() => {
    const doms = ['cover.', 'vacuum.', 'lawn_mower.', 'lock.', 'alarm_control_panel.'];
    const l = Object.keys(S).filter(id => doms.some(d => id.indexOf(d) === 0)
      || (id.indexOf('binary_sensor.') === 0 && ['door', 'window', 'garage_door', 'opening', 'connectivity', 'motion'].indexOf((S[id].attributes || {}).device_class) >= 0));
    return l.slice(0, 40);
  }, [hass]);
  const reels = grouperJournal(useRoomLogbook(hass, ids));
  const events = demoEvents !== null ? demoEvents : reels;
  const pastille = (id) => {
    const dom = String(id).split('.')[0];
    const dcE = ((S[id] || {}).attributes || {}).device_class;
    if (dcE === 'connectivity') return 'var(--o-text3)';
    if (dom === 'cover') return 'var(--o-purple)';
    if (dom === 'vacuum' || dom === 'lawn_mower') return 'var(--o-ok)';
    if (dom === 'binary_sensor') return 'var(--o-warn)';
    if (dom === 'lock' || dom === 'alarm_control_panel') return 'var(--o-accent-soft)';
    return 'var(--o-accent-soft)';
  };
  const heure = (when) => { const ms = when < 1e12 ? when * 1000 : when; const d = new Date(ms); const auj = new Date(); return d.toDateString() === auj.toDateString() ? d.toLocaleTimeString(locale(), { hour: '2-digit', minute: '2-digit' }) : d.toLocaleDateString(locale(), { weekday: 'short' }); };
  const nomDe = (id) => ((S[id] || {}).attributes || {}).friendly_name || String(id).split('.')[1];
  return (
    <div className="o-piece" style={{ ...CV_CADRE, height: '100%', minHeight: 172, overflow: 'hidden' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <span style={{ fontSize: 13, fontWeight: 700 }}>{tr('Activité récente')}</span>
        <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--o-text3)' }}>{new Date().toLocaleTimeString(locale(), { hour: '2-digit', minute: '2-digit' })}</span>
      </div>
      {/* De l'AIR entre l'en-tête et les lignes — règle dure, comme partout. */}
      <div style={{ flex: 1, minHeight: 12 }} />
      {events.length === 0 && <div style={{ fontSize: 12, color: 'var(--o-text3)', fontWeight: 600, padding: '10px 0' }}>{tr('Rien à raconter')}</div>}
      {events.slice(0, 4).map((e, i) => (
        <div key={(e.when || 0) + '|' + i} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '4px 0' }}>
          <span style={{ width: 7, height: 7, borderRadius: '50%', flexShrink: 0, background: pastille(e.entity_id) }} />
          <span style={{ flex: 1, minWidth: 0, fontSize: 12, fontWeight: 700, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{e.message || (nomDe(e.entity_id) + ' ' + etatJournal(e.entity_id, e.state, S).toLowerCase())}{e.n > 1 ? ' ·×' + e.n : ''}</span>
          <span style={{ fontSize: 11, fontWeight: 600, flexShrink: 0, color: 'var(--o-text3)' }}>{heure(e.when)}</span>
        </div>
      ))}
    </div>
  );
}

/* Décompte d'un panneau qui s'arme (ou qui laisse le temps de désarmer).
 *
 * Home Assistant ne normalise pas ce délai : Alarmo publie `delay` (le total
 * de la phase en cours, en secondes), les autres nomment cela `arming_time`,
 * `delay_time` ou `pending_time`. On prend le premier connu et on le compte
 * depuis `last_changed`, l'instant où la phase a commencé. Sans délai publié,
 * pas de décompte inventé — la carte dit simplement l'activation en cours.
 * Renvoie { reste, total } en secondes, ou null. */
function armCompte(st) {
  if (!st || (st.state !== 'arming' && st.state !== 'pending')) return null;
  const a = st.attributes || {};
  const total = [a.delay, a.arming_time, a.delay_time, a.pending_time]
    .map(v => (v == null ? NaN : +v)).find(v => !isNaN(v) && v > 0);
  if (total == null) return null;
  const debut = Date.parse(st.last_changed || st.last_updated || '');
  if (isNaN(debut)) return null;
  const reste = Math.ceil(total - (Date.now() - debut) / 1000);
  return { reste: Math.max(0, Math.min(total, reste)), total };
}
/* Un battement par seconde, seulement quand quelque chose décompte : sans
 * `actif`, aucun minuteur ne tourne. */
function useSeconde(actif) {
  const [, tic] = useState(0);
  useEffect(() => {
    if (!actif) return undefined;
    const iv = setInterval(() => tic(n => n + 1), 1000);
    return () => clearInterval(iv);
  }, [actif]);
}

/* Vers QUEL mode un panneau est en train de s'armer. Alarmo l'annonce dans
 * `arm_mode`, d'autres intégrations dans `next_state` ; à défaut on retient le
 * mode que l'écran vient de demander (`optimiste`). Renvoie le SERVICE du
 * bouton concerné, ou null quand le panneau ne dit rien — auquel cas on ne
 * devine pas, on garde la barre. */
function armVise(st, optimiste) {
  const a = (st && st.attributes) || {};
  const parEtat = { armed_away: 'alarm_arm_away', armed_home: 'alarm_arm_home', armed_night: 'alarm_arm_night', armed_vacation: 'alarm_arm_vacation' };
  const dit = a.arm_mode || a.next_state || a.arming_mode || null;
  if (dit && parEtat[dit]) return parEtat[dit];
  return { away: 'alarm_arm_away', home: 'alarm_arm_home', night: 'alarm_arm_night' }[optimiste] || null;
}

/* La progression de l'armement tracée SUR le bouton du mode visé : le tour se
 * referme, et le bouton est cerné quand l'alarme prend. Un rect SVG normalisé
 * (`pathLength=100`) avance à vitesse constante le long du périmètre, ce qu'un
 * dégradé conique ne fait pas sur une forme large. Le trait déborde de moitié,
 * rogné par l'`overflow` du bouton : il reste collé au bord. */
function ArmAnneau({ pct, col = 'var(--o-warn2)', r = 9 }) {
  const p = Math.max(0, Math.min(100, pct));
  return (
    <svg width="100%" height="100%" aria-hidden="true" focusable="false" style={{ position: 'absolute', inset: 0, pointerEvents: 'none' }}>
      <rect x="0" y="0" width="100%" height="100%" rx={r} ry={r} fill="none" stroke={col} strokeWidth="3"
        pathLength="100" strokeDasharray="100" strokeDashoffset={100 - p}
        style={{ transition: 'stroke-dashoffset 1s linear' }} />
    </svg>
  );
}

/* L'ARMEMENT en tête du rail de l'accueil : c'est le geste du départ et du
 * retour, il ne devrait pas demander d'ouvrir une vue. Les modes proposés sont
 * ceux du panneau ; s'il réclame un code, on ouvre la vue Sécurité, qui sait le
 * demander. Composant à part pour battre la seconde du décompte sans faire
 * tictaquer tout l'accueil. */
/* Armements RÉELLEMENT offerts par un panneau, lus dans `supported_features`
 * (bits Home Assistant : 1 = maison, 2 = absent, 4 = nuit, 32 = vacances).
 * Alarmo ne déclare que les modes configurés : n'afficher que ceux-là évite
 * de proposer un geste qui ne ferait rien. Un panneau muet sur ses capacités
 * garde les deux armements courants — mieux vaut deux boutons de trop qu'une
 * carte sans aucun geste.
 * Renvoie [libellé, service, actif] — « Désarmé » d'abord, toujours. */
function armChips(attrs, etat) {
  const f = +((attrs || {}).supported_features) || 0;
  const out = [[tr('Désarmé'), 'alarm_disarm', etat === 'disarmed']];
  const veut = (bit) => (f ? !!(f & bit) : bit === 1 || bit === 2);
  if (veut(1)) out.push([tr('Maison'), 'alarm_arm_home', etat === 'armed_home']);
  if (veut(2)) out.push([tr('Absent'), 'alarm_arm_away', etat === 'armed_away']);
  if (veut(4)) out.push([tr('Nuit'), 'alarm_arm_night', etat === 'armed_night']);
  if (veut(32)) out.push([tr('Vacances'), 'alarm_arm_vacation', etat === 'armed_vacation']);
  // Un panneau armé dans un mode qu'il ne déclare pas ne doit pas paraître
  // désarmé : sa chip rejoint la liste plutôt que de mentir.
  const connus = { armed_home: [1, tr('Maison'), 'alarm_arm_home'], armed_away: [2, tr('Absent'), 'alarm_arm_away'], armed_night: [4, tr('Nuit'), 'alarm_arm_night'], armed_vacation: [32, tr('Vacances'), 'alarm_arm_vacation'] }[etat];
  if (connus && !out.some(c => c[1] === connus[2])) out.push([connus[1], connus[2], true]);
  return out;
}

/* Alarme : l'état et les gestes que le panneau offre. Le désarmement passe par
 * le service ; si le panneau exige un code, Home Assistant refusera — comme
 * partout. */
/* Sirene (ADR 0034) : la carte de la vue Securite — au gabarit maison, icone
 * en haut a gauche, bascule a droite, nom SOUS l'icone, puis l'etat. Les
 * tuiles ne disent que ce que l'entite expose (`available_tones`,
 * `volume_level`) : ni volume ni delai inventes. « Test sonore » sonne trois
 * secondes, TENUES PAR HOME ASSISTANT (`sirene.py`, ADR 0065) : par
 * `duration` quand la sirene le gere, sinon le composant l'eteint lui-meme.
 * L'onglet ne compte plus rien — fermer l'ecran pendant le test n'a plus
 * d'effet — et une sirene qui sonne pour de vrai ne se teste pas. */
function CvSirene({ id, hass, label = null }) {
  const st = hass && hass.states ? hass.states[id] : null;
  const s = st ? st.state : null;
  const a = (st && st.attributes) || {};
  const mort = !st || s === 'unavailable' || s === 'unknown';
  const on = !mort && s === 'on';
  const nom = label || cvName(st, id);
  // Une sirene en `switch` s'allume et s'eteint comme un interrupteur.
  const dom = String(id).split('.')[0];
  const call = (svc, data) => commanderService(hass, id, dom, svc, { entity_id: id, ...(data || {}) });
  const [test, setTest] = useState(false);
  const [erreur, setErreur] = useState('');
  // Le bouton se libere a la fin que le serveur annonce : un affichage, rien
  // de plus — l'extinction, elle, part de Home Assistant.
  const finTestRef = useRef(0);
  useEffect(() => () => clearTimeout(finTestRef.current), []);
  const tester = () => {
    if (mort || test || !hass || typeof hass.callWS !== 'function') return;
    setTest(true); setErreur('');
    hass.callWS({ type: 'loggia/sirene/tester', entity_id: id })
      .then((r) => { finTestRef.current = setTimeout(() => setTest(false), Math.max(1, Number(r && r.duree) || 3) * 1000); })
      .catch((e) => { setTest(false); setErreur(e && e.code === 'unauthorized' ? tr('Ce compte ne pilote pas cet appareil.') : tr('Le test n’a pas pu partir.')); });
  };
  const col = on ? 'var(--o-bad)' : 'var(--o-text3)';
  const tuiles = [];
  if (Array.isArray(a.available_tones) && a.available_tones.length) tuiles.push([tr('Sonneries'), String(a.available_tones.length)]);
  if (typeof a.volume_level === 'number') tuiles.push([tr('Volume'), Math.round(a.volume_level * 100) + ' %']);
  return (
    <div className={'o-piece' + (mort ? ' o-panne' : '')} style={{ ...CV_CADRE, height: '100%', minHeight: 172, overflow: 'hidden' }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <span style={RM_ICO(on ? 'rgba(var(--o-bad-rgb),.16)' : 'var(--o-s1)', col)}><GlypheCarte id={id} size={16}><Fi i="bell-ring" size={16} /></GlypheCarte></span>
        {!mort && <RmBascule on={on} nom={nom} onToggle={() => call(on ? 'turn_off' : 'turn_on')} />}
      </div>
      <div style={{ marginTop: 10, flex: 1, display: 'flex', flexDirection: 'column' }}>
        <div style={RM_NAME}>{nom}</div>
        <div style={{ ...RM_SUB, color: erreur ? 'var(--o-bad)' : mort ? 'var(--o-text3)' : col }}>{erreur || (mort ? tr('Indisponible') : on ? tr('Sirène active') : tr('Sirène au repos'))}</div>
        {/* Ce que l'entite expose (sonneries, volume) tient sur UNE ligne : en
          * tuiles, la carte montait a 223 px et entrainait toute sa rangee — le
          * format standard est de 184 px (retour du 17/09). */}
        {!mort && tuiles.length > 0 && <div style={RM_SUB}>{tuiles.map(([l, v]) => l + ' ' + v).join(' · ')}</div>}
        <div style={{ flex: 1 }} />
        {!mort && <button type="button" onClick={tester} disabled={test} className="o-rmbtn" style={{ ...RM_BTN, marginTop: 11, width: '100%', opacity: test ? .6 : 1 }}><Fi i="volume" size={12} /> {test ? tr('Test en cours…') : tr('Test sonore (3 s)')}</button>}
      </div>
    </div>
  );
}

/* `message` (ADR 0034) : ce que la carte a a dire entre son nom et ses
 * boutons — un ouvrant ouvert a l'armement, un capteur contourne, par quoi
 * l'alarme s'est declenchee. Rien a dire : rien d'affiche. */
function CvAlarm({ id, hass, sans = false, message = null, label = null }) {
  const st = hass && hass.states ? hass.states[id] : null;
  const s = st ? st.state : null;
  const aAl = (st && st.attributes) || {};
  const call = (svc, code) => commanderService(hass, id, 'alarm_control_panel', svc, { entity_id: id, ...(code ? { code } : {}) });
  // Si le panneau exige un code (code_format), on le demande avant d'agir :
  // Home Assistant refuserait silencieusement sans lui.
  const codeRequis = !!aAl.code_format;
  const codePourArm = codeRequis && aAl.code_arm_required !== false;
  const [demande, setDemande] = useState(null); // { svc } en attente de code
  const [code, setCode] = useState('');
  const agir = (svc) => {
    const faut = svc === 'alarm_disarm' ? codeRequis : codePourArm;
    if (faut) { setDemande({ svc }); setCode(''); } else call(svc);
  };
  const valider = () => { if (demande && code) { call(demande.svc, code); setDemande(null); setCode(''); } };
  // Le temps qu'il reste pour sortir (ou pour désarmer), battu à la seconde.
  const cpt = armCompte(st);
  useSeconde(!!cpt);
  // Le mode que le panneau prépare : son bouton portera le tour de progression.
  const svcVise = cpt ? armVise(st, null) : null;
  /* `enPanne`, comme CvCard (05/10). Morte, l'alarme disait « Armée » en
   * ambre — toute valeur inconnue l'était — et ses modes s'armaient dans le
   * vide ; c'est elle aussi le bloc de l'appareil dans FicheAppareil. Un
   * code en cours de saisie quand elle tombe ne part pas non plus. */
  const mort = enPanne(id, st);
  const [txt, col] = mort ? [tr('Indisponible'), 'var(--o-text3)'] : s === 'disarmed' ? [tr('Désarmée'), 'var(--o-ok)']
    : s === 'triggered' ? [tr('ALERTE'), 'var(--o-bad)']
      : (s === 'arming' || s === 'pending') ? [cpt ? tr('Activation dans {n} s', { n: cpt.reste }) : tr('Activation en cours…'), 'var(--o-warn2)']
        : s ? [tr('Armée'), 'var(--o-warn2)'] : ['—', 'var(--o-text3)'];
  // Les chips SUIVENT le panneau : `supported_features` dit quels armements
  // existent (Alarmo n'expose que les modes configurés). Proposer « Maison »
  // à un panneau qui l'ignore, c'est promettre un geste sans effet.
  const CHIPS = mort ? [] : armChips(aAl, s);
  return (
    <div className={'o-piece o-carte-alarme' + (mort ? ' o-panne' : '')} style={{ ...CV_CADRE, height: '100%', minHeight: 172, overflow: 'hidden' }}>
      {/* GABARIT MAISON — règle dure : icône hg SEULE, état hd, TITRE SOUS
        * L'ICÔNE avec de l'air. Jamais côte à côte, maquette ou pas. */}
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <span style={{ width: 34, height: 34, borderRadius: 10, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: hx(col, .16), color: col }}><GlypheCarte id={id} size={15}><Fi i="shield-check" size={15} /></GlypheCarte></span>
        <span style={{ fontSize: 11, fontWeight: 800, color: col }}>{txt}</span>
      </div>
      <div style={{ marginTop: 8, ...(sans ? { flex: 1, display: 'flex', flexDirection: 'column' } : {}) }}>
        <div style={RM_NAME}>{label || cvName(st, id)}</div>
        {/* Le message se DIT aussi (audit du 03/10, règle de l'ADR 0107) : il
          * arrive quand l'alarme s'arme sur un ouvrant resté ouvert, ou se
          * déclenche — la carte est déjà à l'écran, et un encadré monté avec
          * son texte ne s'annonçait pas. La région est donc toujours là, vide
          * tant qu'il n'y a rien ; l'encadré reste pour l'œil. Poli : c'est un
          * état, pas la réponse à un geste. */}
        <div className="o-vh" role="status">{message && message.texte ? message.texte : ''}</div>
        {message && message.texte && (
          <div aria-hidden="true" style={{ display: 'flex', alignItems: 'flex-start', gap: 8, marginTop: 8, padding: '8px 10px', borderRadius: 10, background: message.niveau === 'danger' ? 'rgba(var(--o-bad-rgb),.12)' : 'rgba(var(--o-warn-rgb),.12)', color: message.niveau === 'danger' ? 'var(--o-bad)' : 'var(--o-warn)', fontSize: 12, fontWeight: 700, lineHeight: 1.3 }}>
            <Fi i="triangle-warning" size={13} style={{ marginTop: 1, flexShrink: 0 }} />
            <span style={{ minWidth: 0 }}>{message.texte}</span>
          </div>
        )}
        {/* Le temps qui reste se lit sur le tour du mode visé (voir plus bas).
          * Panneau muet sur ce qu'il prépare : la barre reste le repère. */}
        {cpt && !svcVise && (
          <div aria-hidden="true" style={{ height: 4, borderRadius: 4, background: 'var(--o-s1)', overflow: 'hidden', margin: '8px 0 2px' }}>
            <div style={{ height: '100%', width: Math.round((cpt.reste / cpt.total) * 100) + '%', background: col, transition: 'width 1s linear' }} />
          </div>
        )}
        {/* Version « seule » : les chips descendent au pied de la carte,
          * comme les boutons des cartes machines. */}
        {sans && <div style={{ flex: 1 }} />}
        {demande && !mort ? (
          <div style={{ display: 'flex', gap: 8, margin: '7px 0 6px', alignItems: 'center' }}>
            <input type="password" inputMode="numeric" autoFocus value={code} onChange={(e) => setCode(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter') valider(); if (e.key === 'Escape') setDemande(null); }}
              placeholder={tr('Code')} aria-label={tr('Code')}
              style={{ flex: 1, minWidth: 0, padding: '6px 10px', borderRadius: 10, border: 'none', background: 'var(--o-s1)', color: 'var(--o-text)', fontSize: 13, fontWeight: 700, letterSpacing: '.2em' }} />
            <button onClick={valider} style={{ padding: '6px 12px', borderRadius: 10, border: 'none', background: 'var(--o-accent-fond)', color: '#fff', fontWeight: 800, fontSize: 12, cursor: 'pointer', flexShrink: 0 }}>{tr('Valider')}</button>
            <button onClick={() => setDemande(null)} aria-label={tr('Annuler')} style={{ width: 30, height: 30, borderRadius: 10, border: 'none', background: 'var(--o-s1)', color: 'var(--o-text2)', fontWeight: 800, cursor: 'pointer', flexShrink: 0 }}>✕</button>
          </div>
        ) : (
          /* Le mot d'une chip ne se TRONQUE jamais (« Dés », « Mais ») : quand la
           * carte est trop etroite pour ses modes, il s'efface et l'icone reste —
           * requete de conteneur, d'apres le nombre de chips (index.css). */
          <div className="o-armchips" data-n={CHIPS.length} style={{ display: 'flex', gap: 8, margin: '7px 0 6px' }}>
            {CHIPS.map(([lbl, svc, actif]) => (
              <button key={svc} onClick={() => agir(svc)} aria-label={lbl} aria-pressed={actif} className="o-armchip" title={lbl}
                style={{ position: 'relative', flex: 1, padding: sans ? '10px 4px' : '6px 4px', borderRadius: 10, border: 'none', fontSize: 12, fontWeight: 800, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', cursor: 'pointer', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6, background: actif ? 'var(--o-accent-fond)' : 'var(--o-s1)', color: actif ? '#fff' : 'var(--o-text2)' }}>
                {/* L'icone du mode, et le mot — qui s'efface au telephone
                  * (retour user du 16/09 : « on ne les voit pas bien »). */}
                <Fi i={ICONES_ARMEMENT[svc] || 'shield'} size={13} />
                {(cpt && svcVise === svc) ? <span>{cpt.reste + ' s'}</span> : <span className="o-armchip-txt">{lbl}</span>}
                {/* Le tour se referme au rythme du décompte : à zéro, le mode
                  * visé est cerné — l'alarme prend. */}
                {cpt && svcVise === svc && <ArmAnneau pct={100 - (cpt.reste / cpt.total) * 100} col={col} />}
              </button>
            ))}
          </div>
        )}
        {/* Le tour de la maison : ouvrants et caméras — sauf en version
          * « seule » (sans capteurs). Les caméras viennent de la
          * CONFIGURATION d'abord (comme la vue Sécurité), la découverte
          * camera.* en repli. */}
        {!sans && (() => {
          const S = (hass && hass.states) || {};
          const os = ouvrantsDe(S);
          const ouverts = os.filter(o => o.on).length;
          const cfgCams = (() => { try { const c = cfgVal('loggia_cameras', null); return Array.isArray(c) ? c.map(x => x && x.haid).filter(Boolean) : []; } catch { return []; } })();
          const camIds = cfgCams.length ? cfgCams : Object.keys(S).filter(cid => cid.indexOf('camera.') === 0);
          const cams = camIds.filter(cid => S[cid] && S[cid].state !== 'unavailable').length;
          // Lignes nues, sans fond ni contour (retour 31/08).
          const ligne = (l, v, c) => (
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '3px 0' }}>
              <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--o-text1)' }}>{l}</span>
              <span style={{ fontSize: 12, fontWeight: 800, color: c }}>{v}</span>
            </div>
          );
          if (!os.length && !camIds.length) return null;
          return (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
              {os.length > 0 && ligne(tr('Ouvrants'), ouverts === 0 ? tr('{n} fermés', { n: os.length }) : trN(ouverts, '{n} ouvert', '{n} ouverts'), ouverts ? 'var(--o-warn)' : 'var(--o-ok)')}
              {camIds.length > 0 && ligne(tr('Caméras'), tr('{n} en ligne', { n: cams }), 'var(--o-text2)')}
            </div>
          );
        })()}
      </div>
    </div>
  );
}

/* Journal : les dernières entrées du logbook pour CETTE entité. */
function CvJournal({ id, hass }) {
  // Journal d'UNE entité : ne fusionner que les états identiques qui se
  // répètent — fusionner par entité viderait la carte de son sujet.
  const events = grouperJournal(useRoomLogbook(hass, useMemo(() => [id], [id])), (e) => (e.entity_id || '') + '|' + (e.state != null ? e.state : e.message));
  const S = (hass && hass.states) || {};
  const st = S[id];
  /* L'heure dit le jour quand ce n'est plus aujourd'hui (audit du 03/10) :
   * « 16:00 » seul datait du jour un événement de lundi. Le crochet ne rend
   * plus que les dernières 24 h et relit la minute : la ligne passe à
   * « hier » au premier coup de minuit. */
  return (
    <div className="o-piece" style={{ ...CV_CADRE, height: '100%', overflow: 'hidden' }}>
      <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 2, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{cvName(st, id)}</div>
      <div style={{ fontSize: 11, color: 'var(--o-text2)', fontWeight: 600, marginBottom: 4 }}>{tr('Journal')}</div>
      {events.length === 0 && <div style={{ fontSize: 12, color: 'var(--o-text3)', fontWeight: 600, padding: '10px 0' }}>{tr('Rien à raconter')}</div>}
      {events.slice(0, 3).map((e, i) => (
        <div key={(e.when || 0) + '|' + i} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 0', borderTop: 'var(--o-bw,1px) solid var(--o-bd3)' }}>
          <span style={{ flex: 1, fontSize: 12, fontWeight: 700, color: 'var(--o-text1)' }}>{e.state != null ? etatJournal(id, e.state, S) : (e.message || '')}{e.n > 1 ? ' ·×' + e.n : ''}</span>
          <span style={{ fontSize: 11, fontWeight: 600, color: 'var(--o-text3)', flexShrink: 0, whiteSpace: 'nowrap' }}>{heureJournal(e.when)}</span>
        </div>
      ))}
    </div>
  );
}

/* Graphique 24 h : l'historique du capteur en filigrane, la valeur en clair.
 * L'API historique de HA est un GET (pattern des autres lectures d'historique
 * du fichier) : relecture au montage puis toutes les cinq minutes. */
function CvHistory({ id, hass, demoPoints = null, onOpen = null }) {
  // La bibliothèque injecte un historique FACTICE : le hook tourne quand
  // même (ordre des hooks), ses données sont simplement ignorées.
  const pointsReels = useHistorique24(hass, id);
  const points = demoPoints !== null ? demoPoints : pointsReels;
  const st = hass && hass.states ? hass.states[id] : null;
  const a = (st && st.attributes) || {};
  const mort = !st || st.state === 'unavailable';
  // Une date, une heure (05/10, suite « dates partout ») : `texteDate`, sans
  // courbe ni min/max — la carte d'un capteur daté traçait l'année, et
  // l'écrivait en grand, « 2 026 ».
  const date = mort ? null : texteDate(st);
  const cur = st && date == null ? parseFloat(st.state) : NaN;
  // L'ÉNERGIE (kWh, compteur croissant) se raconte en BARRES par heure —
  // chaque barre est le delta du compteur sur l'heure. Le reste en courbe.
  const estEnergie = a.device_class === 'energy' || /Wh$/.test(a.unit_of_measurement || '');
  let chemin = '', aire = '', vmin = null, vmax = null, barres = null, totalJour = null;
  if (date == null && Array.isArray(points) && points.length > 1) {
    if (estEnergie) {
      const seaux = new Map();
      points.forEach(p => { const h = Math.floor(p.t / 3600000); const b = seaux.get(h) || { min: p.v, max: p.v }; b.min = Math.min(b.min, p.v); b.max = Math.max(b.max, p.v); seaux.set(h, b); });
      const parHeure = [...seaux.keys()].sort((x, y) => x - y).map(h => Math.max(0, seaux.get(h).max - seaux.get(h).min));
      // DIX barres au plus : des heures regroupées en tranches larges — vingt-
      // quatre barres fines « ressemblaient à rien » (retour d'essai).
      const N = Math.min(10, parHeure.length);
      barres = Array.from({ length: N }, (_, i) => {
        const de = Math.floor(i * parHeure.length / N), a = Math.floor((i + 1) * parHeure.length / N);
        return parHeure.slice(de, a).reduce((s, v) => s + v, 0);
      });
      totalJour = parHeure.reduce((s, v) => s + v, 0);
    } else {
      const t0 = points[0].t, t1 = points[points.length - 1].t || t0 + 1;
      vmin = Math.min(...points.map(p => p.v)); vmax = Math.max(...points.map(p => p.v));
      const spread = (vmax - vmin) || 1;
      const X = (t) => ((t - t0) / (t1 - t0 || 1)) * 100;
      const Y = (v) => 34 - ((v - vmin) / spread) * 28;
      chemin = points.map((p, i) => (i ? 'L' : 'M') + X(p.t).toFixed(1) + ' ' + Y(p.v).toFixed(1)).join(' ');
      aire = chemin + ` L 100 40 L 0 40 Z`;
    }
  }
  const bmax = barres && barres.length ? Math.max(...barres, 0.001) : 1;
  const valeur = date != null ? date : isNaN(cur) ? '—' : decMax(cur, 1);
  const unite = date != null ? '' : a.unit_of_measurement || '';
  const nom = cvName(st, id);
  return (
    /* eslint-disable-next-line jsx-a11y/no-static-element-interactions, jsx-a11y/no-noninteractive-tabindex */
    <div className={'o-piece' + (mort ? ' o-panne' : '')} role={onOpen ? 'button' : undefined} tabIndex={onOpen ? 0 : undefined}
      aria-label={onOpen ? nomCarte(nom, date == null && isNaN(cur) ? (mort ? tr('Indisponible') : null) : (unite ? valeur + ' ' + unite : valeur)) : undefined} aria-haspopup={onOpen ? 'dialog' : undefined}
      onClick={onOpen ? () => onOpen(id) : undefined}
      onKeyDown={onOpen ? (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onOpen(id); } } : undefined}
      style={{ ...CV_CADRE, height: '100%', minHeight: 150, position: 'relative', overflow: 'hidden', opacity: mort ? .55 : 1, cursor: onOpen ? 'pointer' : undefined }}>
      {chemin && (
        <svg viewBox="0 0 100 40" preserveAspectRatio="none" style={{ position: 'absolute', left: 0, right: 0, bottom: 0, width: '100%', height: '58%' }}>
          <path d={aire} fill="rgba(var(--o-accent-rgb),.10)" />
          <path d={chemin} fill="none" stroke="var(--o-accent)" strokeWidth="1.4" vectorEffect="non-scaling-stroke" />
        </svg>
      )}
      {/* Barres en éléments pleins, coins nets — la dernière porte l'accent. */}
      {barres && barres.length > 0 && (
        <div aria-hidden="true" style={{ position: 'absolute', left: 12, right: 12, bottom: 10, height: '48%', display: 'flex', alignItems: 'flex-end', gap: 6 }}>
          {barres.map((v, i) => (
            <div key={i} style={{ flex: 1, minWidth: 0, height: Math.max(8, (v / bmax) * 100) + '%', borderRadius: 10, background: i === barres.length - 1 ? 'var(--o-accent-fond)' : 'rgba(var(--o-accent-rgb),.35)' }} />
          ))}
        </div>
      )}
      <div style={{ position: 'relative', fontSize: 13, fontWeight: 700, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{nom}</div>
      <div style={{ position: 'relative', fontSize: 25, fontWeight: 800, marginTop: 2 }}>{valeur}<span style={{ fontSize: 13, fontWeight: 700, color: 'var(--o-text2)', marginLeft: 4 }}>{unite}</span></div>
      <div style={{ position: 'relative', marginTop: 'auto', fontSize: 11, fontWeight: 600, color: 'var(--o-text3)' }}>
        {date != null ? null : points === null ? tr('Chargement…') : points === 'erreur' ? tr('Historique indisponible pour le moment') : points.length < 2 ? tr("Pas d'historique sur 24 h")
          : estEnergie ? tr('{n} sur 24 h', { n: decMax(totalJour, 1) + ' ' + (a.unit_of_measurement || 'kWh') })
            : (tr('min {a} · max {b}', { a: decMax(vmin, 1), b: decMax(vmax, 1) }))}
      </div>
    </div>
  );
}

/* ── Cartes AGRÉGATS (sans entité d'ancrage, comme l'horloge) ────────────────
 * Elles lisent la maison entière : découverte par device_class ou
 * configuration existante — zéro YAML, sources injectables pour la biblio. */
const OUVRANT_DCS = ['door', 'window', 'garage_door', 'opening', 'gate'];
/* Les entites que la BANNIERE et la carte Securite comptent, une par une
 * plutot que par domaine.
 *
 * Surveiller `binary_sensor.` en entier reveillerait l'accueil pour un
 * capteur de vibration ou une pile ; on ne prend que ce qui se lit a
 * l'ecran : les ouvrants, le mouvement (la ligne d'etat de Securite, v3.29),
 * la surete (« A surveiller »), plus les cameras et les panneaux d'alarme.
 * Sans cette liste, a l'inverse, la banniere lit des etats que rien ne la
 * fait relire : elle garde une fenetre ouverte a l'ecran apres sa fermeture,
 * et cache un media qui vient de demarrer.
 */
const bannerKeys = () => {
  const S = (getHass() || {}).states || {};
  const out = [];
  for (const id in S) {
    const p = id.indexOf('.');
    const dom = p > 0 ? id.slice(0, p) : '';
    if (dom === 'media_player' || dom === 'camera' || dom === 'alarm_control_panel' || APPAREIL_ACTIF[dom]) { out.push(id); continue; }
    if (dom !== 'binary_sensor') continue;
    const dc = (S[id].attributes || {}).device_class;
    if (OUVRANT_DCS.indexOf(dc) >= 0 || CLASSES_MOUVEMENT.indexOf(dc) >= 0 || CLASSES_SURETE.indexOf(dc) >= 0) out.push(id);
  }
  return out;
};
const ouvrantsDe = (S) => Object.keys(S || {})
  .filter(id => id.indexOf('binary_sensor.') === 0 && S[id] && S[id].state !== 'unavailable')
  .map(id => ({ id, dc: (S[id].attributes || {}).device_class, on: S[id].state === 'on', nom: (S[id].attributes || {}).friendly_name || id, lc: S[id].last_changed }))
  .filter(o => OUVRANT_DCS.indexOf(o.dc) >= 0);
const airDe = (S) => {
  const par = (dcs) => Object.keys(S || {}).filter(id => id.indexOf('sensor.') === 0 && S[id] && dcs.indexOf((S[id].attributes || {}).device_class) >= 0 && !isNaN(parseFloat(S[id].state)));
  const maxDe = (ids) => ids.length ? ids.reduce((m, id) => parseFloat(S[id].state) > parseFloat(S[m].state) ? id : m, ids[0]) : null;
  const moyDe = (ids) => ids.length ? ids.reduce((s, id) => s + parseFloat(S[id].state), 0) / ids.length : null;
  const co2 = maxDe(par(['carbon_dioxide']));
  return {
    co2, co2V: co2 ? Math.round(parseFloat(S[co2].state)) : null,
    vocV: (() => { const v = maxDe(par(['volatile_organic_compounds', 'volatile_organic_compounds_parts'])); return v ? Math.round(parseFloat(S[v].state)) : null; })(),
    pmV: (() => { const v = maxDe(par(['pm25'])); return v ? Math.round(parseFloat(S[v].state)) : null; })(),
    humV: (() => { const v = moyDe(par(['humidity'])); return v != null ? Math.round(v) : null; })(),
  };
};
/* Qualité d'air : le CO₂ le plus haut de la maison en vedette, verdict en
 * badge, les autres mesures en sous-tuiles. */
function CvAir({ hass }) {
  const S = (hass && hass.states) || {};
  const air = airDe(S);
  // Le verdict de la table de confort, comme les cartes des capteurs.
  const vAir = air.co2V == null ? null : verdictMesure('co2', air.co2V);
  const [txt, col] = vAir ? [vAir.t, vAir.c] : ['—', 'var(--o-text3)'];
  const tuile = (l, v) => v != null && (
    <div style={{ flex: 1, minWidth: 0, padding: '5px 9px', borderRadius: 10, background: 'var(--o-s1)' }}>
      <div style={{ fontSize: 10, fontWeight: 700, color: 'var(--o-text3)' }}>{l}</div>
      <div style={{ fontSize: 12, fontWeight: 800, whiteSpace: 'nowrap' }}>{v}</div>
    </div>
  );
  return (
    <div className="o-piece" style={{ ...CV_CADRE, height: '100%', minHeight: 172, overflow: 'hidden' }}>
      {/* Gabarit maison : icône hg, verdict hd, TITRE SOUS L'ICÔNE. */}
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <span style={RM_ICO(hx(col, .14), col)}><Fi i="smog" size={16} /></span>
        <span style={{ fontSize: 11, fontWeight: 800, padding: '3px 9px', borderRadius: 999, background: hx(col, .14), color: col }}>{txt}</span>
      </div>
      <div style={{ marginTop: 8 }}>
        <div style={RM_NAME}>{tr('Qualité air')}</div>
        <div style={{ fontSize: 19, fontWeight: 800, marginTop: 1 }}>{air.co2V != null ? air.co2V : '—'}<span style={{ fontSize: 12, fontWeight: 700, color: 'var(--o-text2)', marginLeft: 5 }}>ppm CO₂</span></div>
        <div style={{ height: 5, borderRadius: 4, background: 'var(--o-bd1)', margin: '6px 0 7px', overflow: 'hidden' }}>
          <div style={{ height: '100%', width: Math.min(100, (air.co2V || 0) / 20) + '%', background: col, borderRadius: 4, transition: 'width .3s' }} />
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          {tuile(tr('COV'), air.vocV != null ? air.vocV + ' ppb' : null)}
          {tuile('PM2.5', air.pmV != null ? air.pmV + ' µg' : null)}
          {tuile(tr('Humidité'), air.humV != null ? air.humV + ' %' : null)}
        </div>
      </div>
    </div>
  );
}
/* Toute la maisonnée, sans limite : la carte n'en montre que ce que 184 px
 * peuvent porter. Même patron que les autres feuilles (ADR 0055) : hauteur au
 * contenu, une croix en bout de ligne d'en-tête. Chaque ligne dit où est la
 * personne et depuis quand, comme la carte d'une personne seule. */
function FeuillePresence({ liste, onClose }) {
  const maison = liste.filter(p => p.home).length;
  return (
    <BottomSheet onClose={onClose}>
      <TitreFeuille marge={12}>
        <span style={{ display: 'flex', alignItems: 'baseline', gap: 10, minWidth: 0 }}>
          <span style={{ fontSize: 17, fontWeight: 800 }}>{tr('Présence')}</span>
          <span style={{ fontSize: 12, fontWeight: 800, color: maison ? 'var(--o-ok)' : 'var(--o-text3)' }}>{maison + ' / ' + liste.length}</span>
        </span>
      </TitreFeuille>
      <div role="list">
        {liste.map((p) => (
          <div key={p.haid} role="listitem" style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '9px 0', borderTop: 'var(--o-bw,1px) solid var(--o-bd3)' }}>
            <span aria-hidden="true" style={{ width: 34, height: 34, borderRadius: '50%', flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: p.img ? `url("${p.img}") center/cover` : 'var(--o-s1)', fontSize: 12, fontWeight: 800, color: p.home ? 'var(--o-text2)' : 'var(--o-text3)', opacity: p.home || !p.img ? 1 : .55 }}>{!p.img && p.name.slice(0, 2).toUpperCase()}</span>
            <span style={{ flex: 1, minWidth: 0 }}>
              <span style={{ display: 'block', fontSize: 14, fontWeight: 800, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{p.name}</span>
              <span style={{ display: 'block', fontSize: 12, fontWeight: 600, color: p.home ? 'var(--o-ok)' : 'var(--o-text3)' }}>{(p.home ? tr('À la maison') : tr('Absent')) + (p.lc ? ' · ' + relTime(p.lc).toLowerCase() : '')}</span>
            </span>
            <span aria-hidden="true" style={{ width: 9, height: 9, borderRadius: '50%', flexShrink: 0, background: p.home ? 'var(--o-ok)' : 'var(--o-text3)', boxShadow: p.home ? '0 0 6px rgba(var(--o-ok-rgb),.6)' : 'none' }} />
          </div>
        ))}
      </div>
    </BottomSheet>
  );
}
/* Présence : toute la maisonnée. Jusqu'à trois personnes, une ligne chacune —
 * avatar, où, depuis quand. À partir de quatre, la ligne déborderait le format
 * standard (deux rangées de 88 px, règle du projet) : une grille d'avatars,
 * quatre par rangée, deux rangées — huit tiennent —, et « +n » sur la dernière
 * case au-delà (ADR 0088). L'ordre est celui de la configuration : une famille
 * connaît les places, et l'avatar estompé dit déjà l'absence. Un toucher ouvre
 * la feuille, où tout le monde tient sans limite. */
function CvPresence({ hass, gens = null }) {
  const S = (hass && hass.states) || {};
  const liste = (gens || peopleList()).map(p => {
    const st = S[p.haid];
    return { ...p, home: !!st && st.state === 'home', lc: st && st.last_changed };
  });
  const maison = liste.filter(p => p.home).length;
  const [ouvert, setOuvert] = useState(false);
  const ouvrable = liste.length > 0;
  // Le compteur affiché en haut à droite, et lu dans le nom de la carte.
  const compteur = maison + ' / ' + liste.length;
  /* Relecture du lot 13 : un rôle bouton rend sa descendance
   * présentationnelle — qui est là (« Alice · À la maison ») ne se lisait
   * nulle part. Ces textes se lisent en DESCRIPTION, au focus : le nom et
   * l'état de chaque ligne (pas l'avatar, dont les initiales se liraient),
   * sinon la grille, dont chaque case porte déjà son nom. */
  const did = useId();
  const decrit = !ouvrable ? undefined : liste.length <= 3 ? liste.map(p => did + p.haid).join(' ') : did + '-g';
  const etat = (p) => p.home ? tr('À la maison') : tr('Absent');
  const avatar = (p, taille) => (
    <span aria-hidden="true" style={{ position: 'relative', width: taille, height: taille, flexShrink: 0 }}>
      <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', width: '100%', height: '100%', borderRadius: '50%', background: p.img ? `url("${p.img}") center/cover` : 'var(--o-s1)', fontSize: 10, fontWeight: 800, color: p.home ? 'var(--o-text2)' : 'var(--o-text3)', opacity: p.home || !p.img ? 1 : .55 }}>{!p.img && p.name.slice(0, 2).toUpperCase()}</span>
      <span style={{ position: 'absolute', right: -2, bottom: -2, width: 9, height: 9, borderRadius: '50%', background: p.home ? 'var(--o-ok)' : 'var(--o-text3)', border: '2px solid var(--o-surfA)', boxShadow: p.home ? '0 0 6px rgba(var(--o-ok-rgb),.6)' : 'none' }} />
    </span>
  );
  return (<>
    {/* Ouvrable, la carte EST un bouton (rôle, tabulation, Entrée et Espace) :
      * elle ne porte aucune commande. Vide, elle n'est rien de tout cela.
      * Son nom est ce qu'elle affiche, « Présence, 1 / 2 », et elle dit
      * ouvrir une feuille (lot 13 de l'audit du 03/10) : « Ouvrir Présence »
      * taisait combien étaient là. */}
    {/* eslint-disable-next-line jsx-a11y/no-static-element-interactions, jsx-a11y/no-noninteractive-tabindex */}
    <div className="o-piece o-carte-presence" role={ouvrable ? 'button' : undefined} tabIndex={ouvrable ? 0 : undefined} aria-label={ouvrable ? nomCarte(tr('Présence'), compteur) : undefined} aria-haspopup={ouvrable ? 'dialog' : undefined} aria-describedby={decrit}
      onClick={ouvrable ? () => setOuvert(true) : undefined}
      onKeyDown={ouvrable ? (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setOuvert(true); } } : undefined}
      style={{ ...CV_CADRE, height: '100%', minHeight: 172, overflow: 'hidden', cursor: ouvrable ? 'pointer' : 'default' }}>
      {/* Gabarit maison : icône hg, compteur hd, TITRE SOUS L'ICÔNE. */}
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <span style={RM_ICO(maison ? 'rgba(var(--o-ok-rgb),.14)' : 'var(--o-s1)', maison ? 'var(--o-ok)' : 'var(--o-text3)')}><Fi i="users" size={16} /></span>
        {liste.length > 0 && <span style={{ fontSize: 11, fontWeight: 800, color: maison ? 'var(--o-ok)' : 'var(--o-text3)' }}>{compteur}</span>}
      </div>
      <div style={{ marginTop: 8 }}>
        <div style={RM_NAME}>{tr('Présence')}</div>
        {liste.length === 0 && <div style={{ fontSize: 12, color: 'var(--o-text3)', fontWeight: 600, padding: '10px 0' }}>{tr('Personne de configuré')}</div>}
        {liste.length <= 3 && liste.map((p) => (
          <div key={p.haid} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '3px 0', borderTop: 'var(--o-bw,1px) solid var(--o-bd3)', marginTop: 2 }}>
            <span style={{ width: 22, height: 22, borderRadius: '50%', flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: p.img ? `url("${p.img}") center/cover` : 'var(--o-s1)', fontSize: 10, fontWeight: 800, color: p.home ? 'var(--o-text2)' : 'var(--o-text3)', opacity: p.home || !p.img ? 1 : .55 }}>{!p.img && p.name.slice(0, 2).toUpperCase()}</span>
            <span style={{ flex: 1, minWidth: 0, fontSize: 12, fontWeight: 700, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }} id={did + p.haid}>{p.name}<span className="o-presence-ou" style={{ fontWeight: 600, color: 'var(--o-text3)' }}> · {etat(p)}</span></span>
            <span style={{ width: 7, height: 7, borderRadius: '50%', flexShrink: 0, background: p.home ? 'var(--o-ok)' : 'var(--o-text3)', boxShadow: p.home ? '0 0 6px rgba(var(--o-ok-rgb),.6)' : 'none' }} />
          </div>
        ))}
        {liste.length > 3 && (
          <div className="o-presence-grille" id={did + '-g'} role="list" style={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: '4px 4px', marginTop: 2 }}>
            {(liste.length > 8 ? liste.slice(0, 7) : liste).map((p) => (
              <div key={p.haid} role="listitem" title={p.name + ' · ' + etat(p)} aria-label={p.name + ' · ' + etat(p)} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2, minWidth: 0 }}>
                {avatar(p, 26)}
                <span className="o-presence-nom" aria-hidden="true" style={{ maxWidth: '100%', fontSize: 10.5, fontWeight: 700, color: p.home ? 'var(--o-text1)' : 'var(--o-text3)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{p.name}</span>
              </div>
            ))}
            {liste.length > 8 && (
              <div role="listitem" title={trN(liste.length - 7, '{n} autre personne', '{n} autres personnes')} aria-label={trN(liste.length - 7, '{n} autre personne', '{n} autres personnes')} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2, minWidth: 0 }}>
                <span aria-hidden="true" style={{ width: 26, height: 26, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--o-s1)', fontSize: 10.5, fontWeight: 800, color: 'var(--o-text2)' }}>{'+' + (liste.length - 7)}</span>
                <span className="o-presence-nom" aria-hidden="true" style={{ fontSize: 10.5, fontWeight: 700, color: 'var(--o-text3)' }}>{'…'}</span>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
    {ouvert && <FeuillePresence liste={liste} onClose={() => setOuvert(false)} />}
  </>);
}
/* Ouvrants : portes, fenêtres, garage — l'état de chaque ouverture, et le
 * verdict d'ensemble en tête. */
function CvOuvrants({ hass }) {
  const S = (hass && hass.states) || {};
  const os = ouvrantsDe(S);
  const ouverts = os.filter(o => o.on).length;
  const icoDe = (dc) => dc === 'window' ? 'window-alt' : (dc === 'garage_door' || dc === 'gate') ? 'garage' : 'door-closed';
  // Les ouverts d'abord : c'est eux qu'on cherche.
  const tri = [...os].sort((a, b) => (b.on ? 1 : 0) - (a.on ? 1 : 0));
  return (
    <div className="o-piece" style={{ ...CV_CADRE, height: '100%', minHeight: 172, overflow: 'hidden' }}>
      {/* Gabarit maison : icône hg, verdict hd, TITRE SOUS L'ICÔNE. */}
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <span style={RM_ICO(ouverts ? 'rgba(var(--o-warn-rgb),.16)' : 'var(--o-s1)', ouverts ? 'var(--o-warn)' : 'var(--o-text3)')}><Fi i={ouverts ? 'door-open' : 'door-closed'} size={16} /></span>
        <span style={{ fontSize: 11, fontWeight: 800, color: ouverts ? 'var(--o-warn)' : 'var(--o-ok)' }}>{os.length === 0 ? '—' : ouverts === 0 ? tr('Tout fermé') : trN(ouverts, '{n} ouvert', '{n} ouverts')}</span>
      </div>
      <div style={{ marginTop: 10 }}>
        <div style={RM_NAME}>{tr('Ouvrants')}</div>
        {os.length === 0 && <div style={{ fontSize: 12, color: 'var(--o-text3)', fontWeight: 600, padding: '10px 0' }}>{tr('Aucun capteur d’ouverture')}</div>}
        {tri.slice(0, 3).map((o) => (
          <div key={o.id} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '3px 0', borderTop: 'var(--o-bw,1px) solid var(--o-bd3)', marginTop: 2 }}>
            <Fi i={o.on && o.dc === 'door' ? 'door-open' : icoDe(o.dc)} size={12} color={o.on ? 'var(--o-warn)' : 'var(--o-text3)'} />
            <span style={{ flex: 1, fontSize: 12, fontWeight: 700, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{o.nom}</span>
            <span style={{ fontSize: 11, fontWeight: 800, flexShrink: 0, color: o.on ? 'var(--o-warn)' : 'var(--o-ok)' }}>{o.on ? (tr('Ouvert') + (o.lc ? ' ' + relTime(o.lc).toLowerCase() : '')) : tr('Fermée')}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
/* Énergie maison : la consommation du moment en vedette, la part solaire en
 * badge, les flux en sous-tuiles. Les rôles viennent du tableau Énergie. */
function CvEnergie({ hass, roles = null }) {
  const S = (hass && hass.states) || {};
  const EN = roles || enHaids();
  /* En watts et en kWh, quelle que soit l'unité du capteur (audit du 03/10) :
   * un compteur P1/DSMR en kW s'affichait « 3 W », un compteur en Wh mille
   * fois trop grand. `null` sans valeur lisible : la tuile ne paraît pas. */
  const lit = (id, de) => (id && S[id] ? de(S[id]) : null);
  const sol = lit(EN.solarNow, wattsDe), grid = lit(EN.gridNow, wattsDe);
  /* Sans compteur réseau lisible, la consommation de la maison est inconnue
   * (audit du 03/10) : `grid || 0` faisait du solaire seul TOUTE la maison,
   * la pastille annonçait « Solaire 100 % » dès que le compteur se taisait,
   * et la barre se peignait en réseau ; elle reste vide désormais. Un solaire
   * muet compte pour rien, lui : un onduleur éteint la nuit ne produit pas.
   * Le réseau garde son SIGNE (relecture du 03/10) : un compteur net passe
   * sous zéro à l'export, et `Math.max(0, grid)` faisait de « solaire 3000 W,
   * réseau −2000 W » une maison à 3000 W au lieu de 1000 — le double de
   * l'export, quand la vue Énergie dit 1000. */
  const maison = grid != null ? Math.max(0, Math.round((sol || 0) + grid)) : null;
  const part = maison && sol != null ? Math.round(Math.min(100, sol / maison * 100)) : null;
  const jour = lit(EN.consoJour, kwhDe);
  const tuile = (l, v, c) => v != null && (
    <div style={{ flex: 1, minWidth: 0, padding: '5px 9px', borderRadius: 10, background: 'var(--o-s1)' }}>
      <div style={{ fontSize: 10, fontWeight: 700, color: 'var(--o-text3)' }}>{l}</div>
      <div style={{ fontSize: 12, fontWeight: 800, whiteSpace: 'nowrap', color: c || 'var(--o-text)' }}>{v}</div>
    </div>
  );
  return (
    <div className="o-piece" style={{ ...CV_CADRE, height: '100%', minHeight: 172, overflow: 'hidden' }}>
      {/* Gabarit maison : icône hg, part solaire hd, TITRE SOUS L'ICÔNE. */}
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <span style={RM_ICO('rgba(var(--o-accent-rgb),.14)', 'var(--o-accent-soft)')}><Fi i="bolt" size={16} /></span>
        {part != null && <span style={{ fontSize: 11, fontWeight: 800, padding: '3px 9px', borderRadius: 999, background: 'rgba(var(--o-ok-rgb),.14)', color: 'var(--o-ok)' }}>{tr('Solaire')} {part} %</span>}
      </div>
      <div style={{ marginTop: 8 }}>
        <div style={RM_NAME}>{tr('Énergie maison')}</div>
        <div style={{ fontSize: 19, fontWeight: 800, marginTop: 1 }}>{maison != null ? maison : '—'}<span style={{ fontSize: 12, fontWeight: 700, color: 'var(--o-text2)', marginLeft: 5 }}>W</span></div>
        <div style={{ display: 'flex', height: 5, borderRadius: 4, background: 'var(--o-bd1)', margin: '6px 0 7px', overflow: 'hidden' }}>
          <div style={{ width: (part || 0) + '%', background: 'var(--o-ok)', transition: 'width .3s' }} />
          <div style={{ width: (maison != null ? 100 - (part || 0) : 0) + '%', background: 'var(--o-accent-fond)', opacity: .8, transition: 'width .3s' }} />
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          {tuile(tr('Solaire'), sol != null ? Math.round(sol) + ' W' : null, 'var(--o-ok)')}
          {tuile(tr('Réseau'), grid != null ? Math.round(grid) + ' W' : null, 'var(--o-accent-soft)')}
          {tuile(tr("Aujourd'hui"), jour != null ? decMax(jour, 1) + ' kWh' : null)}
        </div>
      </div>
    </div>
  );
}
/* Électroménager : cycle en cours — progression, fin prévue, consommation.
 * À PROPS pour l'instant (biblio) : le branchement config viendra. */
function ApplianceCard({ nom, etat, pct, restant, fin, conso, chip = false }) {
  if (chip) {
    return (
      <div className="o-piece o-cvdense" style={{ position: 'relative', height: '100%', boxSizing: 'border-box', display: 'flex', flexDirection: 'column', justifyContent: 'center', padding: '12px 14px', borderRadius: 'var(--o-radius,18px)', background: 'linear-gradient(180deg,var(--o-surfA),var(--o-surfB))', border: LISERE, boxShadow: 'var(--o-shadow,0 10px 26px rgba(0,0,0,.3))' }}>
        <div className="o-cvrow" style={{ display: 'flex', alignItems: 'center' }}>
          <span className="o-cvico" style={{ flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(var(--o-purple-rgb),.16)', color: 'var(--o-purple)' }}><Fi i="soap" size={15} /></span>
          <div className="o-cvtxt">
            <div style={{ fontSize: 14, fontWeight: 700, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{nom}</div>
            <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--o-purple)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{etat}</div>
          </div>
          {restant && <span style={{ fontSize: 14, fontWeight: 800, flexShrink: 0 }}>{restant}</span>}
        </div>
      </div>
    );
  }
  const tuile = (l, v) => v != null && (
    <div style={{ flex: 1, minWidth: 0, padding: '5px 9px', borderRadius: 10, background: 'var(--o-s1)' }}>
      <div style={{ fontSize: 10, fontWeight: 700, color: 'var(--o-text3)' }}>{l}</div>
      <div style={{ fontSize: 12, fontWeight: 800, whiteSpace: 'nowrap' }}>{v}</div>
    </div>
  );
  return (
    <div className="o-piece" style={{ ...CV_CADRE, height: '100%', minHeight: 172, overflow: 'hidden' }}>
      {/* Gabarit maison : icône hg, temps restant hd, TITRE SOUS L'ICÔNE. */}
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <span style={RM_ICO('rgba(var(--o-purple-rgb),.16)', 'var(--o-purple)')}><Fi i="soap" size={16} /></span>
        {restant && <span style={{ fontSize: 13, fontWeight: 800, flexShrink: 0, color: 'var(--o-purple)' }}>{restant}</span>}
      </div>
      <div style={{ marginTop: 8 }}>
        <div style={RM_NAME}>{nom}</div>
        <div style={{ ...RM_SUB, color: 'var(--o-purple)' }}>{etat}</div>
        <div style={{ height: 5, borderRadius: 4, background: 'var(--o-bd1)', margin: '7px 0 7px', overflow: 'hidden' }}>
          <div style={{ height: '100%', width: Math.min(100, pct || 0) + '%', background: 'var(--o-purple)', borderRadius: 4, transition: 'width .3s' }} />
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          {tuile(tr('Fin prévue'), fin)}
          {tuile(tr('Conso cycle'), conso)}
        </div>
      </div>
    </div>
  );
}

/* Le calendrier en grand : le mois entier, et le choix des agendas.
 *
 * La carte du rail dit la semaine ; elle ne peut pas dire le mois sans
 * devenir illisible. Le clic ouvre donc ce que la carte resume, avec la
 * meme grammaire — anneau sur les jours qui portent un rendez-vous, pastille
 * sur aujourd'hui — pour qu'on reconnaisse la semaine qu'on vient de voir.
 *
 * Le jour choisi montre ses evenements dessous. Un mois sans cela ne serait
 * qu'un almanach : on saurait QUE quelque chose arrive, jamais quoi.
 */
/* Créer un rendez-vous depuis le dashboard.
 *
 * Home Assistant sait le faire par `calendar.create_event`, mais seulement pour
 * les agendas qui le déclarent : un calendrier en lecture seule — un flux
 * d'anniversaires, un abonnement iCal — n'a pas le bit `CREATE_EVENT`. La liste
 * `cals` est donc filtrée par la capacité, en amont : mieux vaut ne pas montrer
 * le bouton que d'ouvrir un formulaire qui finira refusé.
 *
 * Le service prend la date par DEUX paires exclusives. Avec une heure,
 * `start_date_time` et `end_date_time` ; pour une journée entière, `start_date`
 * et `end_date`, cette dernière EXCLUSIVE — un rendez-vous d'un seul jour finit
 * le lendemain. C'est la convention iCalendar, et l'oublier fabrique un
 * événement de durée nulle que rien n'affiche.
 */

function FeuilleCalendrier({ hass, onClose }) {
  const S = (hass && hass.states) || {};
  const nbEntites = Object.keys(S).length;
  const tousCals = useMemo(() => Object.keys(S).filter(k => k.indexOf('calendar.') === 0).sort(), [nbEntites]);
  /* Les agendas retenus. Rien de choisi = tous : une maison qui n'a jamais
   * ouvert ce reglage doit voir son calendrier, pas un mois vide. */
  const [choisis, setChoisis] = useState(() => {
    const c = cfgVal('loggia_agendas', null);
    return Array.isArray(c) && c.length ? c.filter(x => typeof x === 'string') : null;
  });
  const [reglages, setReglages] = useState(false);
  const [nouveau, setNouveau] = useState(false);
  /* Incremente apres une creation : le sondage de l'agenda relit aussitot,
   * au lieu d'attendre son quart d'heure. */
  const [tick, setTick] = useState(0);
  const [edition, setEdition] = useState(null);
  /* L'uid du rendez-vous dont on demande confirmation avant d'effacer. Un
   * seul a la fois : deux confirmations ouvertes, c'est un clic de trop au
   * mauvais endroit. */
  const [confirme, setConfirme] = useState(null);
  const [errListe, setErrListe] = useState(null);
  const choisisSig = choisis ? choisis.join('|') : '';
  const calsSig = tousCals.join('|');
  const actifs = useMemo(() => {
    const l = (choisis || tousCals).filter(k => tousCals.indexOf(k) >= 0);
    return l.length ? l : tousCals;
  }, [choisisSig, calsSig]);

  const auj = new Date(); auj.setHours(0, 0, 0, 0);
  const [ancre, setAncre] = useState(() => new Date(auj.getFullYear(), auj.getMonth(), 1));
  const [choisi, setChoisi] = useState(() => new Date(auj));

  /* La grille commence au LUNDI qui precede le 1er et tient six semaines :
   * un mois qui commence un dimanche en occupe six, et une grille qui change
   * de hauteur d'un mois a l'autre fait sauter tout ce qui est dessous. */
  const ancreMs = ancre.getTime();
  const debutGrille = useMemo(() => {
    const d = new Date(ancre); d.setDate(1 - ((ancre.getDay() + 6) % 7)); d.setHours(0, 0, 0, 0); return d;
  }, [ancreMs]);
  const debutMs = debutGrille.getTime();
  // Compté sur le calendrier (agenda.js, `jourPlus`) : six semaines de 24 h
  // finissaient à 23 h la veille dès que la grille passait l'heure d'hiver.
  const finGrille = useMemo(() => jourPlus(new Date(debutMs), 42), [debutMs]);
  const finMs = finGrille.getTime();
  const plage = useMemo(() => ({ debut: debutGrille, fin: finGrille }), [debutMs, finMs]);
  const events = useAgenda(hass, actifs, plage, tick);
  /* Les agendas qui acceptent qu'on y ecrive. Un flux d'anniversaires ou un
   * abonnement iCal n'a pas le bit `CREATE_EVENT` : sans ce filtre, le bouton
   * s'afficherait pour ouvrir un formulaire condamne d'avance. Calcule a
   * chaque rendu — il y a une poignee d'agendas, pas un millier. */
  const calsEcrivables = tousCals.filter(k => peut(hass, k, 'creer_evenement'));
  /* Le CHOIX des agendas reste aux administrateurs (03/10). Il ecrit
   * `loggia_agendas` — quels calendriers la maison montre : de la
   * configuration, pas de l'agencement — que `store.py` refuse a un compte
   * Home Assistant ordinaire. Lui proposer les cases, c'etait lui servir un
   * refus a chaque clic, et un choix qui revenait au rechargement : le geste
   * se masque. La LECTURE reste a tous, il voit les agendas retenus
   * (`actifs`). Seul un `false` explicite masque, comme dans la vue
   * Systeme : sans compte connu, le serveur tranchera. Le critere est celui
   * de tous les gestes masques (`compteOrdinaire`, state.js). */
  const ordinaire = compteOrdinaire(hass);

  /* Supprimer.
   *
   * `portee` vaut '' pour la seule occurrence — le defaut de Home Assistant —
   * ou 'THISANDFUTURE' pour celle-ci et les suivantes. `recurrence_id` ne part
   * que s'il existe : sur un rendez-vous unique il n'y en a pas, et l'envoyer
   * vide ferait echouer la commande. */
  const supprimer = async (e, portee) => {
    const options = {};
    if (e.recurrence_id) {
      options.recurrence_id = e.recurrence_id;
      if (portee) options.recurrence_range = portee;
    }
    const p = actionsPlan(e._cal, 'supprimer_evenement', e.uid, actionCtx(hass), options);
    if (!p.ok) { setErrListe(p.reason || tr('Home Assistant a refusé.')); return; }
    const r = await runPlan(hass, p);
    if (!r || !r.ok) { setErrListe((r && r.reason) ? String(r.reason) : tr('Home Assistant a refusé.')); return; }
    setConfirme(null); setErrListe(null); setTick(t => t + 1);
  };

  const dateDe = (e) => new Date(e.start.dateTime || (e.start.date + 'T00:00:00'));
  const parJour = useMemo(() => {
    const m = new Map();
    for (const e of events) { const k = cleJour(dateDe(e)); if (!m.has(k)) m.set(k, []); m.get(k).push(e); }
    return m;
  }, [events]);

  const jours = useMemo(() => Array.from({ length: 42 }, (_, i) => jourPlus(new Date(debutMs), i)), [debutMs]);
  const duJour = parJour.get(cleJour(choisi)) || [];
  const moisAns = ancre.toLocaleDateString(locale(), { month: 'long', year: 'numeric' });
  const bougerMois = (n) => {
    const d = new Date(ancre.getFullYear(), ancre.getMonth() + n, 1);
    setAncre(d);
    // Le jour choisi suit le mois, sinon la liste du bas parlerait d'un jour
    // qui n'est plus a l'ecran.
    setChoisi(d.getFullYear() === auj.getFullYear() && d.getMonth() === auj.getMonth() ? new Date(auj) : d);
  };
  const basculer = (k) => {
    const base = choisis || tousCals;
    const suiv = base.indexOf(k) >= 0 ? base.filter(x => x !== k) : base.concat(k);
    // Tout decocher reviendrait a un mois vide sans rien dire : on garde au
    // moins celui qu'on vient de toucher.
    const val = suiv.length ? suiv : [k];
    setChoisis(val);
    cfgSet({ loggia_agendas: val.length === tousCals.length ? null : val });
  };
  const heureDe = (e) => e.start.dateTime
    ? dateDe(e).toLocaleTimeString(locale(), { hour: '2-digit', minute: '2-digit' })
    : tr('journée');
  const nomCal = (id) => ((S[id] || {}).attributes || {}).friendly_name || id.replace('calendar.', '');

  const btnRond = { width: 34, height: 34, borderRadius: '50%', border: 'none', background: 'var(--o-s1)', color: 'var(--o-text1)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 };
  return (
    <BottomSheet onClose={onClose}>
      {() => (<>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 14 }}>
        <NomFeuille><span style={{ flex: 1, fontSize: 17, fontWeight: 800, textTransform: 'capitalize', letterSpacing: '-.01em' }}>{moisAns}</span></NomFeuille>
        <button onClick={() => bougerMois(-1)} aria-label={tr('Mois précédent')} style={btnRond}><Fi i="angle-left" size={14} /></button>
        <button onClick={() => bougerMois(1)} aria-label={tr('Mois suivant')} style={btnRond}><Fi i="angle-right" size={14} /></button>
        {calsEcrivables.length > 0 && (
          <button onClick={() => { setNouveau(v => !v); setReglages(false); }} aria-label={tr('Nouvel événement')} aria-pressed={nouveau}
            style={{ ...btnRond, background: nouveau ? 'var(--o-accent-fond)' : 'var(--o-s1)', color: nouveau ? '#fff' : 'var(--o-text1)' }}><Fi i="plus" size={14} /></button>
        )}
        {!ordinaire && tousCals.length > 1 && (
          <button onClick={() => { setReglages(v => !v); setNouveau(false); }} aria-label={tr('Choisir les agendas')} aria-pressed={reglages}
            style={{ ...btnRond, background: reglages ? 'var(--o-accent-fond)' : 'var(--o-s1)', color: reglages ? '#fff' : 'var(--o-text1)' }}><Fi i="settings-sliders" size={14} /></button>
        )}
        <CroixFeuille />
      </div>

      {nouveau && calsEcrivables.length > 0 && (
        <NouvelEvenement hass={hass} cals={calsEcrivables} jour={choisi}
          onClose={() => setNouveau(false)}
          onFait={() => { setNouveau(false); setTick(t => t + 1); }} />
      )}

      {edition && (
        <NouvelEvenement hass={hass} cals={calsEcrivables} jour={choisi} evenement={edition}
          onClose={() => setEdition(null)}
          onFait={() => { setEdition(null); setTick(t => t + 1); }} />
      )}

      {reglages && !ordinaire && (
        <div style={{ marginBottom: 14, padding: 12, borderRadius: 16, background: 'var(--o-s1)', display: 'flex', flexDirection: 'column', gap: 8 }}>
          <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: '.06em', color: 'var(--o-text1)', opacity: .78 }}>{tr('AGENDAS AFFICHÉS')}</div>
          {tousCals.map(k => {
            const on = actifs.indexOf(k) >= 0;
            return (
              <button key={k} onClick={() => basculer(k)} aria-pressed={on}
                style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '9px 10px', minHeight: 44, borderRadius: 12, cursor: 'pointer',
                  border: 'var(--o-bw,1px) solid var(--o-bd2)', background: on ? 'rgba(var(--o-accent-rgb),.12)' : 'transparent', color: 'var(--o-text1)', textAlign: 'left' }}>
                <span style={{ width: 20, height: 20, borderRadius: 6, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',
                  background: on ? 'var(--o-accent-fond)' : 'transparent', border: on ? 'none' : 'var(--o-bw,1px) solid var(--o-bd2)' }}>
                  {on && <Fi i="check" size={11} color="#fff" />}
                </span>
                <span style={{ flex: 1, minWidth: 0, fontSize: 13, fontWeight: 700, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{nomCal(k)}</span>
              </button>
            );
          })}
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7,1fr)', rowGap: 5, textAlign: 'center' }}>
        {jours.slice(0, 7).map((d, i) => <span key={'e' + i} style={{ fontSize: 10, fontWeight: 800, letterSpacing: '.04em', color: 'var(--o-text1)', opacity: .78, paddingBottom: 4 }}>{d.toLocaleDateString(locale(), { weekday: 'narrow' })}</span>)}
        {jours.map((d, i) => {
          const cJour = d.getTime() === auj.getTime();
          const sel = d.getTime() === new Date(choisi).setHours(0, 0, 0, 0);
          const horsMois = d.getMonth() !== ancre.getMonth();
          const n = (parJour.get(cleJour(d)) || []).length;
          return (
            <button key={'j' + i} onClick={() => setChoisi(new Date(d))} aria-pressed={sel}
              aria-label={d.toLocaleDateString(locale(), { weekday: 'long', day: 'numeric', month: 'long' }) + (n ? ' · ' + n : '')}
              style={{ position: 'relative', width: 36, height: 36, justifySelf: 'center', border: 'none', background: 'transparent',
                cursor: 'pointer', padding: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              {n > 0 && !cJour && <span aria-hidden="true" style={{ position: 'absolute', inset: 4, borderRadius: '50%', border: (n > 1 ? 2 : 1.5) + 'px solid var(--o-accent-soft)', opacity: horsMois ? .35 : 1 }} />}
              {cJour && <span aria-hidden="true" style={{ position: 'absolute', inset: 4, borderRadius: '50%', background: 'var(--o-accent-fond)' }} />}
              {/* Le jour choisi n'est pas forcement aujourd'hui : il lui faut sa
                * propre marque, sinon on perdrait de vue ce que la liste du bas
                * est en train de raconter. */}
              {sel && !cJour && <span aria-hidden="true" style={{ position: 'absolute', inset: 0, borderRadius: '50%', background: 'var(--o-s1)' }} />}
              {sel && cJour && <span aria-hidden="true" style={{ position: 'absolute', inset: 0, borderRadius: '50%', border: '2px solid var(--o-accent-soft)' }} />}
              <span style={{ position: 'relative', fontSize: 13, fontWeight: cJour || sel ? 800 : n > 0 ? 700 : 600,
                color: cJour ? '#fff' : 'var(--o-text1)', opacity: cJour ? 1 : horsMois ? .78 : n > 0 ? 1 : .9 }}>{d.getDate()}</span>
            </button>
          );
        })}
      </div>

      <div style={{ marginTop: 16, borderTop: 'var(--o-bw,1px) solid var(--o-bd3)', paddingTop: 13 }}>
        <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: '.06em', color: 'var(--o-text1)', opacity: .78, marginBottom: 9, textTransform: 'uppercase' }}>
          {choisi.toLocaleDateString(locale(), { weekday: 'long', day: 'numeric', month: 'long' })}
        </div>
        {duJour.length === 0
          ? <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--o-text1)', opacity: .62, paddingBottom: 4 }}>{tr('Rien de prévu')}</div>
          : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {duJour.map((e, i) => {
                /* Un agenda peut savoir creer sans savoir modifier : les trois
                 * bits sont independants. On demande donc les deux separement,
                 * et l'`uid` en plus — sans lui, aucune des deux commandes ne
                 * sait de quel rendez-vous on parle. */
                const modifiable = !!(e._cal && e.uid && peut(hass, e._cal, 'modifier_evenement'));
                const supprimable = !!(e._cal && e.uid && peut(hass, e._cal, 'supprimer_evenement'));
                const aConfirmer = confirme === e.uid;
                const btnLigne = {
                  width: 32, height: 32, borderRadius: 10, border: 'none', background: 'var(--o-s2)',
                  color: 'var(--o-text1)', cursor: 'pointer', flexShrink: 0,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                };
                const btnTexte = (fort) => ({
                  padding: '8px 12px', minHeight: 36, borderRadius: 10, cursor: 'pointer', fontSize: 12, fontWeight: 700,
                  border: fort ? 'none' : 'var(--o-bw,1px) solid var(--o-bd2)',
                  background: fort ? 'rgba(var(--o-bad-rgb),.16)' : 'transparent',
                  color: fort ? 'var(--o-bad)' : 'var(--o-text1)',
                });
                return (
                  <div key={e.uid || i} style={{ padding: '10px 12px', borderRadius: 13, background: 'var(--o-s1)' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 11 }}>
                      <span style={{ width: 3, alignSelf: 'stretch', minHeight: 26, borderRadius: 2, background: 'var(--o-accent-soft)', flexShrink: 0 }} />
                      <span style={{ flex: 1, minWidth: 0 }}>
                        <span style={{ display: 'block', fontSize: 13, fontWeight: 700, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{e.summary}</span>
                        {tousCals.length > 1 && e._cal && <span style={{ display: 'block', fontSize: 11, fontWeight: 600, color: 'var(--o-text1)', opacity: .6, marginTop: 1 }}>{nomCal(e._cal)}</span>}
                      </span>
                      <span style={{ fontSize: 12, fontWeight: 800, color: 'var(--o-text1)', flexShrink: 0, fontVariantNumeric: 'tabular-nums' }}>{heureDe(e)}</span>
                      {modifiable && (
                        <button onClick={() => { setEdition(e); setNouveau(false); setConfirme(null); }}
                          aria-label={tr('Modifier') + ' · ' + e.summary} style={btnLigne}><Fi i="pencil" size={12} /></button>
                      )}
                      {supprimable && (
                        <button onClick={() => { setConfirme(aConfirmer ? null : e.uid); setErrListe(null); }}
                          aria-label={tr('Supprimer') + ' · ' + e.summary} aria-expanded={aConfirmer}
                          style={{ ...btnLigne, background: aConfirmer ? 'rgba(var(--o-bad-rgb),.16)' : 'var(--o-s2)', color: aConfirmer ? 'var(--o-bad)' : 'var(--o-text1)' }}><Fi i="trash" size={12} /></button>
                      )}
                    </div>

                    {/* Supprimer est irreversible : on demande, et le bouton
                      * dangereux ne se pose pas la ou etait le bouton innocent.
                      * Un rendez-vous qui se repete ouvre un choix de plus —
                      * sans lui, on ne saurait pas si l'on efface une occurrence
                      * ou toute la serie, et le defaut silencieux de Home
                      * Assistant est « celle-ci seulement ». */}
                    {aConfirmer && (
                      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center', marginTop: 10 }}>
                        <span style={{ flex: '1 1 100%', fontSize: 12, fontWeight: 600, color: 'var(--o-text1)', opacity: .8 }}>
                          {e.recurrence_id ? tr('Ce rendez-vous se répète. Que supprimer ?') : tr('Supprimer ce rendez-vous ?')}
                        </span>
                        <button onClick={() => supprimer(e, '')} style={btnTexte(true)}>
                          {e.recurrence_id ? tr('Cette fois') : tr('Supprimer')}
                        </button>
                        {e.recurrence_id && (
                          <button onClick={() => supprimer(e, 'THISANDFUTURE')} style={btnTexte(true)}>{tr('Celle-ci et les suivantes')}</button>
                        )}
                        <button onClick={() => setConfirme(null)} style={btnTexte(false)}>{tr('Annuler')}</button>
                      </div>
                    )}
                    {aConfirmer && errListe && (
                      <div role="alert" style={{ fontSize: 12, fontWeight: 700, color: 'var(--o-bad)', marginTop: 8 }}>{errListe}</div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
      </div>
      </>)}
    </BottomSheet>
  );
}

/* Calendrier : le mois en grille — aujourd'hui à l'accent, un point sous
 * les jours qui portent un événement (7 prochains jours connus). */
function CvCalendrier({ id, hass, onOpen = null }) {
  const events = useAgenda(hass, useMemo(() => [id], [id]));
  const auj = new Date();
  // La SEMAINE courante (lundi → dimanche) : le mois entier étouffait dans le
  // format standard — la référence « April 21 » respire mieux (retour 31/08).
  const lundi = new Date(auj); lundi.setHours(0, 0, 0, 0); lundi.setDate(auj.getDate() - ((auj.getDay() + 6) % 7));
  const semaine = Array.from({ length: 7 }, (_, i) => { const d = new Date(lundi); d.setDate(lundi.getDate() + i); return d; });
  /* Combien d'evenements par jour, pas seulement s'il y en a : deux rendez-vous
   * ne se voient pas comme un seul. */
  const parJour = new Map();
  for (const e of events) {
    const k = cleJour(new Date(e.start.dateTime || (e.start.date + 'T00:00:00')));
    parJour.set(k, (parJour.get(k) || 0) + 1);
  }
  const mois = auj.toLocaleDateString(locale(), { month: 'long' });
  return (
    /* Meme motif que la tuile ci-dessus : tout est conditionne par `onOpen`.
     * La carte ne porte aucune commande : elle reste le bouton. Son nom est
     * ce qu'elle affiche, le mois et le quantieme, et elle dit ouvrir une
     * feuille (lot 13 de l'audit du 03/10) : son ancien nom, un geste,
     * taisait la date qu'on lit. */
    /* eslint-disable-next-line jsx-a11y/no-static-element-interactions, jsx-a11y/no-noninteractive-tabindex */
    <div className="o-piece" onClick={onOpen ? () => onOpen(id) : undefined} tabIndex={onOpen ? 0 : undefined}
      role={onOpen ? 'button' : undefined}
      onKeyDown={onOpen ? (ev) => { if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); onOpen(id); } } : undefined}
      aria-label={onOpen ? nomCarte(tr('Calendrier'), mois + ' ' + auj.getDate()) : undefined} aria-haspopup={onOpen ? 'dialog' : undefined}
      style={{ ...CV_CADRE, height: '100%', minHeight: 172, overflow: 'hidden', cursor: onOpen ? 'pointer' : undefined }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        {/* Le mois et le quantieme au MEME poids, l'un a gauche, l'autre a
          * droite. Le quantieme etait deux fois plus gras : il ecrasait le
          * mois, et la ligne se lisait comme un chiffre suivi d'une legende
          * plutot que comme une date. */}
        <span style={{ fontSize: 31, fontWeight: 300, lineHeight: 1.05, textTransform: 'capitalize', letterSpacing: '-.02em' }}>{mois}</span>
        <span style={{ fontSize: 31, fontWeight: 300, lineHeight: 1.05, letterSpacing: '-.02em' }}>{auj.getDate()}</span>
      </div>
      <div style={{ flex: 1, minHeight: 10 }} />
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7,1fr)', rowGap: 6, textAlign: 'center' }}>
        {semaine.map((d, i) => <span key={'e' + i} style={{ fontSize: 10, fontWeight: 800, letterSpacing: '.04em', color: 'var(--o-text3)', textTransform: 'uppercase' }}>{d.toLocaleDateString(locale(), { weekday: 'narrow' })}</span>)}
        {/* Un point SOUS le jour, et le jour même dans un carré arrondi.
          *
          * C'était l'inverse : un anneau autour du chiffre, épaissi à deux
          * rendez-vous. L'anneau tenait sur une seule ligne, ce qui était son
          * seul mérite — il se confondait avec la pastille d'aujourd'hui, deux
          * cercles concentriques quand les deux tombaient ensemble, et il
          * serrait le chiffre qu'il devait mettre en avant.
          *
          * Le point coûte une ligne de quatre pixels. En échange, le chiffre
          * respire, la marque ne ressemble plus à la pastille, et deux points
          * disent « chargé » plus vite qu'un trait plus épais.
          *
          * Les jours passés s'effacent : la semaine se lit d'un coup, de ce
          * qui est fait vers ce qui vient. */}
        {semaine.map((d, i) => {
          const cJour = d.toDateString() === auj.toDateString();
          const passe = !cJour && d < auj;
          const n = parJour.get(cleJour(d)) || 0;
          return (
            <span key={'j' + i} style={{ justifySelf: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 5 }}>
              {/* Carré arrondi plutôt que rond : il tient le chiffre sans le
                * serrer, et ne peut pas se lire comme un point de plus. */}
              <span style={{ width: 26, height: 26, borderRadius: 9, display: 'flex', alignItems: 'center', justifyContent: 'center',
                background: cJour ? 'var(--o-accent-fond)' : 'transparent' }}>
                <span style={{ fontSize: 12.5, fontWeight: cJour ? 700 : 500,
                  color: cJour ? '#fff' : 'var(--o-text1)', opacity: cJour ? 1 : passe ? .5 : .92 }}>{d.getDate()}</span>
              </span>
              {/* Aujourd'hui garde son point : sans lui, le jour le plus
                * important serait le seul muet sur ce qu'il contient. */}
              <span aria-hidden="true" style={{ height: 4, display: 'flex', gap: 3, alignItems: 'center' }}>
                {n > 0 && Array.from({ length: Math.min(n, 2) }).map((_, k) => (
                  <span key={k} style={{ width: 4, height: 4, borderRadius: '50%',
                    background: 'var(--o-accent-soft)', opacity: passe ? .35 : cJour ? 1 : .85 }} />
                ))}
              </span>
            </span>
          );
        })}
      </div>
    </div>
  );
}
/* Localisation : la maison au centre, chacun placé par distance et cap —
 * AUCUNE tuile externe (règle du projet), l'échelle est logarithmique. */
function CvCarte({ hass, gensDemo = null }) {
  const S = (hass && hass.states) || {};
  const home = (() => { const z = S['zone.home']; const za = (z && z.attributes) || {}; return (za.latitude != null) ? { lat: za.latitude, lon: za.longitude } : null; })();
  const gens = (gensDemo || peopleList()).map(p => {
    const st = S[p.haid]; const a = (st && st.attributes) || {};
    return { ...p, home: !!st && st.state === 'home', lat: a.latitude, lon: a.longitude };
  });
  const km = (a, b) => { const R = 6371, dLa = (b.lat - a.lat) * Math.PI / 180, dLo = (b.lon - a.lon) * Math.PI / 180; const h = Math.sin(dLa / 2) ** 2 + Math.cos(a.lat * Math.PI / 180) * Math.cos(b.lat * Math.PI / 180) * Math.sin(dLo / 2) ** 2; return 2 * R * Math.asin(Math.sqrt(h)); };
  // L'unite de distance de l'installation (mi aux Etats-Unis) : le calcul reste en km,
  // seul l'affichage se convertit.
  const uniteDist = (hass && hass.config && hass.config.unit_system && hass.config.unit_system.length === 'mi') ? 'mi' : 'km';
  const versUniteDist = (valKm) => uniteDist === 'mi' ? valKm * 0.621371 : valKm;
  const cap = (a, b) => Math.atan2((b.lon - a.lon) * Math.cos(b.lat * Math.PI / 180), b.lat - a.lat);
  const maison = gens.filter(g => g.home).length;
  return (
    <div className="o-piece" style={{ ...CV_CADRE, height: '100%', minHeight: 172, overflow: 'hidden' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <span style={{ fontSize: 13, fontWeight: 700 }}>{tr('Localisation')}</span>
        <span style={{ fontSize: 11, fontWeight: 800, color: maison ? 'var(--o-ok)' : 'var(--o-text3)' }}>{gens.length ? maison + ' / ' + gens.length + ' ' + tr('à la maison') : '—'}</span>
      </div>
      <div style={{ flex: 1, position: 'relative', marginTop: 8, borderRadius: 14, background: 'radial-gradient(circle at 50% 50%, rgba(var(--o-accent-rgb),.08), transparent 70%), var(--o-s1)', overflow: 'hidden' }}>
        {/* cercles de distance (échelle log : ~1 km, ~10 km) */}
        {[34, 62].map((r) => <span key={r} aria-hidden="true" style={{ position: 'absolute', left: '50%', top: '50%', width: r * 2, height: r * 2, transform: 'translate(-50%,-50%)', borderRadius: '50%', border: '1px dashed var(--o-bd1)' }} />)}
        <span style={{ position: 'absolute', left: '50%', top: '50%', transform: 'translate(-50%,-50%)', width: 26, height: 26, borderRadius: '50%', background: 'rgba(var(--o-accent-rgb),.18)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--o-accent-soft)' }}><Fi i="home" size={13} /></span>
        {gens.map((g, i) => {
          let x = 50, y = 50, dist = null;
          if (!g.home && home && g.lat != null && g.lon != null) {
            dist = km(home, { lat: g.lat, lon: g.lon });
            const r = Math.min(72, 16 + 30 * Math.log10(1 + dist));
            const c = cap(home, { lat: g.lat, lon: g.lon });
            x = 50 + (r * Math.sin(c)) / 2.2; y = 50 - (r * Math.cos(c)) / 1.4;
          } else if (g.home) { x = 50 + (i % 2 ? 9 : -9); y = 58; }
          else return null; // absent sans position : rien à placer
          return (
            <span key={g.haid} title={g.name + (dist != null ? ' · ' + Math.round(versUniteDist(dist)) + ' ' + uniteDist : '')}
              style={{ position: 'absolute', left: x + '%', top: y + '%', transform: 'translate(-50%,-50%)', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
              <span style={{ width: 20, height: 20, borderRadius: '50%', background: g.img ? `url("${g.img}") center/cover` : 'var(--o-surfA)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 10, fontWeight: 800, color: 'var(--o-text1)', boxShadow: g.home ? '0 0 0 2px var(--o-ok)' : '0 0 0 2px var(--o-bd1)' }}>{!g.img && g.name.slice(0, 2).toUpperCase()}</span>
              <span style={{ fontSize: 10, fontWeight: 700, color: 'var(--o-text2)', whiteSpace: 'nowrap' }}>{g.name}{dist != null ? ' · ' + Math.round(versUniteDist(dist)) + ' ' + uniteDist : ''}</span>
            </span>
          );
        })}
      </div>
    </div>
  );
}

/** La carte d'une entrée de vue custom, selon sa forme et son type. */
function CvTyped({ x, hass, dc }) {
  if (cvEstTpl(x)) return <CvTemplateCard def={x} hass={hass} />;
  // La chaîne nue EST la compacte : une ligne, le contrôle primaire, rien dessous.
  if (typeof x === 'string') return <CvCard id={x} hass={hass} onOpen={dc.ouvrir} dense />;
  const { t, id } = x;
  /* Les cartes capteur ouvrent la fiche 24 h au clic — elles n'ont aucun
   * contrôle interne à protéger. Chacune est elle-même le bouton, nommée de ce
   * qu'elle affiche (lot 13 de l'audit du 03/10) : l'enveloppe d'ici
   * s'appelait « Ouvrir sensor.co2_sejour », l'identifiant épelé. */
  const ouvreCapteur = String(id).split('.')[0] === 'sensor' ? dc.ouvrir : null;
  if (t === 'compacte') return <CvCard id={id} hass={hass} onOpen={dc.ouvrir} dense />;
  // La STANDARD : la carte riche des vues intégrées quand le domaine en a une
  // (volet à curseur, lumière au lavis, thermostat à consigne…) — la carte
  // générique pleine pour le reste (machines, prises…).
  if (t === 'riche') return dc.card(id);
  if (t === 'horloge') return <CvClock />;
  if (t === 'presence') return <CvPresence hass={hass} />;
  if (t === 'activite') return <CvActivite hass={hass} />;
  if (t === 'ouvrants') return <CvOuvrants hass={hass} />;
  if (t === 'energiemaison') return <CvEnergie hass={hass} />;
  if (t === 'air') return <CvAir hass={hass} />;
  if (t === 'chiffre') return <CvBigSensor id={id} hass={hass} onOpen={ouvreCapteur} />;
  if (t === 'jauge') return <CvGauge id={id} hass={hass} onOpen={ouvreCapteur} />;
  if (t === 'graph') return <CvHistory id={id} hass={hass} onOpen={ouvreCapteur} />;
  if (t === 'gros') return <CvBigToggle id={id} hass={hass} />;
  if (t === 'personne') return <CvPerson id={id} hass={hass} />;
  if (t === 'meteo') return <CvWeather id={id} hass={hass} />;
  if (t === 'agenda') return <CvAgenda id={id} hass={hass} />;
  if (t === 'alarme') return <CvAlarm id={id} hass={hass} />;
  if (t === 'alarmeseule') return <CvAlarm id={id} hass={hass} sans />;
  if (t === 'camera') return <CvCamera id={id} hass={hass} />;
  if (t === 'calendrier') return <CvCalendrier id={id} hass={hass} onOpen={dc ? dc.ouvrir : null} />;
  if (t === 'localisation') return <CvCarte hass={hass} />;
  if (t === 'chip') return <CvChip id={id} hass={hass} dc={dc} />;
  if (t === 'chips') return <CvChips x={x} hass={hass} dc={dc} />;
  if (t === 'journal') return <CvJournal id={id} hass={hass} />;
  return <CvCard id={id} hass={hass} onOpen={dc.ouvrir} />;
}

/* ── Bibliothèque de cartes ──────────────────────────────────────────────────
 * Catalogue de TOUTES les cartes de Loggia sur données FICTIVES : on y voit
 * chaque famille même sans posséder les entités. Sert de banc d'essai pour
 * itérer sur le design. Le hass est un faux local — aucun appel ne part. */
const BIBLIO_ART = 'data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2096%2096%22%3E%3Cdefs%3E%3ClinearGradient%20id%3D%22g%22%20x1%3D%220%22%20y1%3D%220%22%20x2%3D%221%22%20y2%3D%221%22%3E%3Cstop%20offset%3D%220%22%20stop-color%3D%22%234c1d95%22%2F%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%230ea5e9%22%2F%3E%3C%2FlinearGradient%3E%3C%2Fdefs%3E%3Crect%20width%3D%2296%22%20height%3D%2296%22%20fill%3D%22url(%23g)%22%2F%3E%3Ccircle%20cx%3D%2248%22%20cy%3D%2248%22%20r%3D%2226%22%20fill%3D%22%23111827%22%2F%3E%3Ccircle%20cx%3D%2248%22%20cy%3D%2248%22%20r%3D%225%22%20fill%3D%22%23f4f4f5%22%2F%3E%3C%2Fsvg%3E';
/* Neuf personnes, pour voir la grille et le « +n » : presents et absents meles. */
const FAMILLE_BIBLIO = ['Camille', 'Alex', 'Marie', 'Sam', 'Noa', 'Lou', 'Éli', 'Maé', 'Zoé'].map((name, i) => ({ name, haid: 'person.biblio' + (i === 0 ? '' : '_' + (i + 1)), img: null }));
/* Les noms de la maison fictive passent par `tr()` (relecture du 03/10) : la
 * Bibliothèque s'ouvre sur une vraie installation, pour tout le monde, et une
 * page anglaise y lisait « Lampe salon », « Thermostat séjour », « Volet
 * chambre ». Comme ceux de la démo (`etiquette`, demo.js), ces noms sont les
 * NÔTRES, pas ceux qu'une maison a tapés ; les prénoms restent tels quels.
 * Appelée au montage (`useState`), la fonction trouve le catalogue chargé.
 * Trois noms rejoignent une clé qui existait : « Alarme maison » y était un
 * geste de scénario (« Alarm home »), l'alarme s'appelle donc « Alarme »
 * comme dans la démo ; « Import réseau » devient « Achat réseau » (« Grid
 * import ») ; « Porte d’entrée » prend l'apostrophe courbe de sa clé.
 * tests/biblio_langue.test.mjs refuse un nom écrit en clair. */
function biblioStates() {
  const il_y_a = (min) => new Date(Date.now() - min * 60000).toISOString();
  const s = (state, attributes) => ({ state: String(state), attributes: attributes || {}, last_changed: il_y_a(12), last_updated: il_y_a(12) });
  return {
    'light.biblio_rgb': s('on', { friendly_name: tr('Lampe salon'), brightness: 178, rgb_color: [255, 170, 60], supported_color_modes: ['rgb', 'color_temp'] }),
    'light.biblio_simple': s('on', { friendly_name: tr('Plafonnier couloir'), supported_color_modes: ['onoff'] }),
    'switch.biblio_prise': s('on', { friendly_name: tr('Prise cafetière') }),
    'climate.biblio': s('heat', { friendly_name: tr('Thermostat séjour'), current_temperature: 20.6, temperature: 21.5, hvac_action: 'heating', hvac_modes: ['off', 'heat', 'cool', 'auto'], preset_modes: ['eco', 'comfort', 'away'], preset_mode: 'comfort', min_temp: 7, max_temp: 30, target_temp_step: .5 }),
    'cover.biblio': s('open', { friendly_name: tr('Volet chambre'), current_position: 65, supported_features: 15 }),
    'media_player.biblio': s('playing', { friendly_name: tr('Enceinte bureau'), media_title: 'Clair de Lune', media_artist: 'Debussy', media_album_name: 'Suite bergamasque', volume_level: .4, supported_features: 20925, entity_picture: BIBLIO_ART }),
    'vacuum.biblio': s('docked', { friendly_name: tr('Aspirateur'), battery_level: 87, supported_features: 4 | 8 | 16 | 512 | 8192, fan_speed: 'standard', fan_speed_list: ['quiet', 'standard', 'turbo'] }),
    'lawn_mower.biblio': s('docked', { friendly_name: tr('Tondeuse'), battery_level: 64, supported_features: 1 | 2 | 4 }),
    'sensor.biblio_temp': s(21.4, { friendly_name: tr('Température séjour'), unit_of_measurement: '°C', device_class: 'temperature' }),
    'sensor.biblio_co2': s(640, { friendly_name: tr('CO₂ séjour'), unit_of_measurement: 'ppm', device_class: 'carbon_dioxide' }),
    'sensor.biblio_puissance': s(1840, { friendly_name: tr('Production solaire'), unit_of_measurement: 'W', device_class: 'power', min: 0, max: 3000 }),
    'person.biblio': s('home', { friendly_name: 'Camille' }),
    'alarm_control_panel.biblio': s('disarmed', { friendly_name: tr('Alarme') }),
    'lock.biblio': s('locked', { friendly_name: tr('Serrure entrée') }),
    'valve.biblio': s('open', { friendly_name: tr('Vanne arrosage') }),
    'scene.biblio': s(il_y_a(95), { friendly_name: tr('Scène cinéma') }),
    'binary_sensor.biblio_porte': s('off', { friendly_name: tr('Porte d’entrée'), device_class: 'door' }),
    // Agrégats : de quoi nourrir Présence, Ouvrants, Qualité d'air, Énergie.
    'person.biblio_2': s('not_home', { friendly_name: 'Alex' }),
    'binary_sensor.biblio_fenetre': s('off', { friendly_name: tr('Fenêtre chambre'), device_class: 'window' }),
    'binary_sensor.biblio_garage': s('on', { friendly_name: tr('Garage'), device_class: 'garage_door' }),
    'sensor.biblio_voc': s(78, { friendly_name: tr('COV bureau'), unit_of_measurement: 'ppb', device_class: 'volatile_organic_compounds' }),
    'sensor.biblio_pm25': s(6, { friendly_name: tr('PM2.5 bureau'), unit_of_measurement: 'µg/m³', device_class: 'pm25' }),
    'sensor.biblio_hum': s(47, { friendly_name: tr('Humidité séjour'), unit_of_measurement: '%', device_class: 'humidity' }),
    'sensor.biblio_solaire': s(486, { friendly_name: tr('Production solaire'), unit_of_measurement: 'W', device_class: 'power' }),
    'sensor.biblio_reseau': s(298, { friendly_name: tr('Achat réseau'), unit_of_measurement: 'W', device_class: 'power' }),
    'sensor.biblio_conso_jour': s(7.4, { friendly_name: tr('Conso du jour'), unit_of_measurement: 'kWh', device_class: 'energy' }),
    'camera.biblio_entree': s('idle', { friendly_name: tr('Caméra entrée') }),
    'camera.biblio_jardin': s('idle', { friendly_name: tr('Caméra jardin') }),
    'binary_sensor.biblio_mouvement': s('on', { friendly_name: tr('Mouvement couloir'), device_class: 'motion' }),
    'calendar.biblio': s('off', { friendly_name: tr('Maison') }),
    'zone.home': s('1', { friendly_name: tr('Maison'), latitude: 46.98, longitude: 1.92, radius: 100 }),
    'person.biblio_3': s('not_home', { friendly_name: 'Marie', latitude: 47.06, longitude: 2.05 }),
    /* Une maisonnee de neuf, pour voir la grille et son « +n » (ADR 0088).
     * Presents et absents meles : c'est l'avatar estompe qui doit se lire. */
    'person.biblio_4': s('home', { friendly_name: 'Sam' }),
    'person.biblio_5': s('not_home', { friendly_name: 'Noa' }),
    'person.biblio_6': s('home', { friendly_name: 'Lou' }),
    'person.biblio_7': s('not_home', { friendly_name: 'Éli' }),
    'person.biblio_8': s('home', { friendly_name: 'Maé' }),
    'person.biblio_9': s('not_home', { friendly_name: 'Zoé' }),
    'person.biblio_10': s('home', { friendly_name: 'Tom' }),
    'person.biblio_11': s('not_home', { friendly_name: 'Ana' }),
    'sensor.biblio_energie_hist': s(7.4, { friendly_name: tr('Énergie maison'), unit_of_measurement: 'kWh', device_class: 'energy' }),
    // Arrivees le 20/09, pour les familles que la bibliotheque ne montrait pas
    // encore : la sirene (retour du 16/09), la meteo (le ciel se fond dans le
    // theme depuis l'ADR 0059) et le soleil, qui dit s'il fait nuit.
    'siren.biblio': s('off', { friendly_name: tr('Sirène intérieure') }),
    'weather.biblio': s('partlycloudy', { friendly_name: tr('Maison'), temperature: 18.2, humidity: 62, temperature_unit: '°C' }),
    // Sans nom (relecture du 03/10) : `sun.sun` ne sert qu'à dire s'il fait
    // nuit, rien ne l'affiche, et « Soleil » est au catalogue un temps qu'il
    // fait (« Sunny »).
    'sun.sun': s('above_horizon'),
  };
}
/* Un scenario fictif, pour la carte des Scenarios : deux actions, lance il y a
 * un moment — de quoi remplir le resume et le repere sans rien inventer. */
const SCN_BIBLIO = () => ({
  // Son nom et la pièce de son action s'affichent (« Lumières à 20 % ·
  // Séjour ») : dans la langue de l'écran (relecture du 03/10).
  id: 'biblio-cinema', nom: tr('Cinéma'), icone: 'film', teinte: 'chambre',
  // `dernier` se compte en SECONDES, comme le serveur le donne.
  dernier: Math.round(Date.now() / 1000) - 95 * 60,
  actions: [
    { famille: 'lumieres', geste: 'niveau', valeur: 20, portee: 'piece', piece: tr('Séjour') },
    { famille: 'volets', geste: 'fermer', portee: 'vie' },
    { famille: 'medias', geste: 'tv' },
  ],
});
